INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('779a37eb-e3c6-6999-ca58-e724ce972192', 'money', 'en', 'MONEY', 'Money Clarity', 'Money Clarity', 'solar:wallet-money-bold-duotone', '#D97706', 'Untangle the pressure and mental load around your money.', 0, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '57450e5b-80ae-17ec-5205-6422c05478b6', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 1, 'Look without judging', 'What would you like to understand about your money right now?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a picture of the situation and missing facts.","weekTitle":"Look without judging","intro":{"title":"Look without judging","note":"Week 1: Look without judging. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"What would you like to understand about your money right now?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["My income","When it arrives","What I need to pay","My debts","My independence","Something else"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write one specific question about your chosen topic.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'bb7af345-2efd-bce3-0428-66136bba7f51', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 2, 'Look without judging', 'How does money currently come into your life?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"How does money currently come into your life?","body":"Choose any that fit. You can also pick none.","elara":"That helps. You can change it any time.","config":{"exclusiveOption":5,"optional":true,"maxSelections":6,"options":["Employment","Clients or sales","Support from others","Benefits","Another source","None right now"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark confirmed versus uncertain income; do not count promises as received money.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '02293b53-8748-2ff5-e571-7c5d12559e79', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 3, 'Look without judging', 'Which payments need your attention before money next arrives?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"Which payments need your attention before money next arrives?","body":"List up to three items; amounts are optional.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Item 1","Item 2","Item 3"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Add a known date or “to confirm” beside each payment.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b9e885dd-eded-8492-ee8e-ca605a1c6c72', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 4, 'Look without judging', 'What best describes the gap between income and essentials?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What best describes the gap between income and essentials?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Enough with some left","Just enough","Not enough","It varies","No income now","Not sure yet"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note whether you need to understand a shortfall, variation, or missing information.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '75e66041-121b-a3df-ce0d-32abac4f6338', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 5, 'Look without judging', 'What information would clarify a payment or income source?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What information would clarify a payment or income source?","body":"A date, amount, frequency or contact; do not upload documents.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Prepare a question for the person or source that could confirm it.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4cad3d2e-945b-a9a2-792b-54f6e8522a1d', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 6, 'Look without judging', 'How would you sketch the flow of money coming in and going out?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"How would you sketch the flow of money coming in and going out?","body":"Use arrows and categories, without account details. You can write a list instead.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Circle one point with missing information as a possible next step.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'aa9a505c-2867-88cc-08a4-d38ef0de0e83', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 7, 'Look without judging', 'What do you now know about your money that you want to keep handy?', NULL, 'reflect', '{"minutes":4,"nextWeekTitle":"Income and possibilities","letter":"This week was about “Look without judging”. What you wrote to keep: “{d7.ask}”. It is yours to reuse, change or leave. Next week: Income and possibilities.","letterFallback":"This week was about “Look without judging”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Income and possibilities."}', NULL, '[{"id":"ask","kind":"reflect","title":"What do you now know about your money that you want to keep handy?","body":"One factual sentence, without judging yourself or promising change.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep your sentence beside one unresolved fact, without turning it into a promise.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0ff76381-d8db-0414-25f5-b93a923c9beb', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 8, 'Income and possibilities', 'Which part of your income would you like to explore first?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: an opportunity criterion and a checkable question.","weekTitle":"Income and possibilities","purpose":"Today you choose where to start looking at your income and turn it into something concrete to find out.","intro":{"title":"Income and possibilities","note":"Every question is optional, and nothing here asks you to contact anyone, spend money or share."}}', NULL, '[{"id":"ask","kind":"choose","title":"Which part of your income would you like to explore first?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"noneOption":5,"options":["Finding work","Improving current work","Following up a payment","Exploring a service or sale","Learning about support","None for now"],"skipLabel":"Prefer to skip","card":{"label":"Your choice"}}},{"id":"take","kind":"reflect","title":"To take with you","body":"What could you find out about this option? Write a question or a small step.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"bodyFallback":"Is there something about your income you would like to understand better? If you want, write it as a question or a small step.","skipLabel":"Prefer to skip","card":{"label":"To take with you","hint":"A question or a small step"}}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ac7da152-27cc-a267-8b58-0a5cd617f6af', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 9, 'Income and possibilities', 'What can you do that might be useful in an opportunity you are considering?', NULL, 'reflect', '{"minutes":4,"purpose":"Today you look for a concrete example in what you already know how to do and turn it into a sentence you could use."}', NULL, '[{"id":"ask","kind":"reflect","title":"What can you do that might be useful in an opportunity you are considering?","body":"Give one concrete example, including informal experience.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip","card":{"label":"What you know how to do"}}},{"id":"take","kind":"reflect","title":"To take with you","body":"Turn your example into a line you could use to describe your experience.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"bodyFallback":"Think of something you know how to do, at home or in informal work too, and write it as one sentence about your experience.","skipLabel":"Prefer to skip","card":{"label":"To take with you","hint":"A sentence about your experience"}}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '66d3f1ea-dc14-3075-236e-79e07038c6f8', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 10, 'Income and possibilities', 'What conditions would make an opportunity workable for you?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What conditions would make an opportunity workable for you?","body":"Choose any that fit. You can also pick none.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"maxSelections":6,"options":["Hours","Caring responsibilities","Transport","Internet access","No upfront payment","Another condition"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark one essential condition before spending time on an offer.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'bb6dbef6-b073-6ea0-b2a0-ac625c4c5390', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 11, 'Income and possibilities', 'What fact could you check before spending time on an opportunity?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What fact could you check before spending time on an opportunity?","body":"For example: duties, hours, requirements or advertised pay. Checking is optional.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note where you would check the fact and what remains unverified.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '10873411-d3ea-98af-0356-3984807aaf6d', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 12, 'Income and possibilities', 'What sentence could you use to ask about work, a price or an outstanding payment?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What sentence could you use to ask about work, a price or an outstanding payment?","body":"Private draft: “I would like to confirm ___.” No need to send it.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the draft; check that it asks for a specific fact without sensitive information.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '563f42df-e2a2-1b09-93ae-fc92344681f1', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 13, 'Income and possibilities', 'What would make you pause and check an offer more carefully?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What would make you pause and check an offer more carefully?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Pay first","Guaranteed earnings","Unclear duties","Sensitive data too early","Pressure to decide","Another signal"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write “Pause and verify” beside your chosen signal. One signal alone does not prove fraud.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b2c39c26-6e32-36a6-c8bf-e2cc6c9a0947', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 14, 'Income and possibilities', 'Which income option, if any, deserves one more small check?', NULL, 'reflect', '{"minutes":4,"nextWeekTitle":"Decide with information","letter":"This week was about “Income and possibilities”. What you wrote to keep: “{d14.ask}”. It is yours to reuse, change or leave. Next week: Decide with information.","letterFallback":"This week was about “Income and possibilities”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Decide with information."}', NULL, '[{"id":"ask","kind":"reflect","title":"Which income option, if any, deserves one more small check?","body":"Name an option and one missing fact. “None for now” is valid.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Define one check that requires no payment or sensitive information.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0ad0f2ca-1a9a-75cb-e090-8cf428e84543', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 15, 'Decide with information', 'Which recent expense would you like to understand before deciding whether to change it?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a question about obligations and a decision criterion.","weekTitle":"Decide with information","intro":{"title":"Decide with information","note":"Week 3: Decide with information. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"Which recent expense would you like to understand before deciding whether to change it?","body":"Describe what it was for without giving the amount.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name the need the expense met before judging it.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e5b5af52-5dfa-e34c-9458-20bd07bd58b7', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 16, 'Decide with information', 'What purpose did that expense, or another you remember, serve?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What purpose did that expense, or another you remember, serve?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["An essential","Work or care","Enjoyment","An unexpected need","A commitment to someone","Another purpose"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note whether that need is likely to remain next time.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3cad52ba-67bc-af27-b32f-8cb8d2a7a552', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 17, 'Decide with information', 'Which recurring payment would you like to review to understand what it includes?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which recurring payment would you like to review to understand what it includes?","body":"Name the payment and what is unclear. This does not mean cancelling it.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Find or note where to see the item and terms; do not cancel on impulse.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '322f6fc5-146e-457c-61cb-fc2a2b9854ae', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 18, 'Decide with information', 'What would you like clarified about a debt or obligation, if you have one?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What would you like clarified about a debt or obligation, if you have one?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Balance","Due date","Instalment","Interest or fees","Terms","Not applicable"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Prepare a question about the chosen fact; if irrelevant, mark “no debt to review.”","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7761c25b-6736-56b4-ba8c-4759ff11ac69', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 19, 'Decide with information', 'What weighs most when you consider helping someone financially?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What weighs most when you consider helping someone financially?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["My essentials","An existing agreement","Wanting to help","Pressure I feel","Limited freedom to decide","Other or not applicable"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write what you would need to know before committing money; no confrontation required.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5d8302bb-5366-95c5-7a16-06406e0bebb5', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 20, 'Decide with information', 'What sentence could give you time before accepting a financial commitment?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What sentence could give you time before accepting a financial commitment?","body":"For example: “I need to check what I can take on.” Only if safe to say.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the sentence as a private draft.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '8fd94b0e-14f1-976f-24e8-e82d73030b3b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 21, 'Decide with information', 'What consideration would you like to remember for your next money decision?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"One concrete attempt","letter":"This week was about “Decide with information”. What you wrote to keep: “{d21.ask}”. It is yours to reuse, change or leave. Next week: One concrete attempt.","letterFallback":"This week was about “Decide with information”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: One concrete attempt."}', NULL, '[{"id":"ask","kind":"reflect","title":"What consideration would you like to remember for your next money decision?","body":"Something specific: check a date, total cost or essentials.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Reduce your criterion to a short check you can remember.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5090b7c4-e754-153c-47e7-1ce5c4fb7f3b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 22, 'One concrete attempt', 'Which small task could give you more clarity this week?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a bounded task, its result, or the actual barrier.","weekTitle":"One concrete attempt","intro":{"title":"One concrete attempt","note":"Week 4: One concrete attempt. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"Which small task could give you more clarity this week?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Confirm income","Clarify a payment","Check an opportunity","Organize notes","Ask for information","Leave it for now"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write its observable result: a fact, response, or note.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f9d970d4-b09c-92f0-077e-79d2b81cbb7d', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 23, 'One concrete attempt', 'What version of that task fits your available time and resources?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What version of that task fits your available time and resources?","body":"If no task was chosen, name what you would need before choosing.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Define the first step; if resources are missing, name that condition.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e47e335b-bc86-a24f-2ada-7f6363b92e86', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 24, 'One concrete attempt', 'What reminder would help you return to your task without having to think it through from scratch?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"What reminder would help you return to your task without having to think it through from scratch?","body":"Optional: photograph a plain note; no names, amounts or account/card documents.","elara":"Noted. Nothing here has to be perfect.","config":{"quiet":true,"optional":true,"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Create a reminder without financial information, as a photo or text.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
