INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4e6c1779-f491-665e-fdb8-8c970bf1684f', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 26, 'One concrete attempt', 'What did you learn from the attempt, or what made it unworkable?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What did you learn from the attempt, or what made it unworkable?","body":"Describe a fact, without judging your discipline.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Separate result from obstacle: no response does not mean you did the task badly.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
