INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f6e244a8-4be2-7c2f-dc82-a9113213f982', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 32, 'Clarity that continues', 'What support or information could help with an unresolved issue?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What support or information could help with an unresolved issue?","body":"Name the kind of help; no contact details or search required.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write a question for a support source appropriate to your situation.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a9d6bc66-8e8d-21fd-68f0-b1092ed9486b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 33, 'Clarity that continues', 'Which brief money check would be useful to repeat?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"Which brief money check would be useful to repeat?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Income dates","Upcoming payments","One obligation","Opportunities or payments owed","My agreements","None for now"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Define what you would check and when the check would be finished.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2dcf6b4d-69a1-0769-0e66-0c7fa2e57f6d', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 34, 'Clarity that continues', 'When would it be useful to review your situation again?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"When would it be useful to review your situation again?","body":"Name a time or event. This does not schedule a reminder.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If useful, note it in your own calendar; the app will not schedule it here.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1ed0bd09-8b11-faa8-bf09-e8ecb746a38c', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'en'), 35, 'Clarity that continues', 'What would you like in your financial clarity note?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"This week was about “Clarity that continues”. What you wrote to keep: “{d35.ask}”. It is yours to reuse, change or leave. That is the whole path. Any day is there if you want to come back to it.","letterFallback":"This week was about “Clarity that continues”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. That is the whole path. Any day is there if you want to come back to it."}', NULL, '[{"id":"ask","kind":"blanks","title":"What would you like in your financial clarity note?","body":"Complete only the lines you want.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["I now know…","Still unresolved…","My next step, if any…"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Check that your note separates facts, open questions, and an optional next step.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('28601b84-b75f-3367-91f8-7ea9cfd76ecc', 'self', 'en', 'SELF', 'Self-Trust', 'Self-Trust', 'solar:sun-fog-bold-duotone', '#945C4F', 'Separate your true voice from the noise of judgment.', 1, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1fe963a3-58f3-5f9b-3564-495d0605b965', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 1, 'Hear your own judgment', 'Which small decision has made you seek approval lately?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a preference and concrete evidence of capability.","weekTitle":"Hear your own judgment","intro":{"title":"Hear your own judgment","note":"Week 1: Hear your own judgment. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"Which small decision has made you seek approval lately?","body":"Choose something everyday; no need to disclose an intimate decision.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name what you hoped for from approval: a fact, company, or permission.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
