INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0c151afd-02bf-fe57-c6f0-b679f4d622c7', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 3, 'Hear your own judgment', 'Which part of that concern do you know, and which part are you imagining?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"Which part of that concern do you know, and which part are you imagining?","body":"A new situation is fine.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Facts","What I imagine"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark one checkable fact and one uncertainty that must remain open.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ee18e01b-7186-1958-5963-589c57163916', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 4, 'Hear your own judgment', 'What past decision worked well enough, even if it was not perfect?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What past decision worked well enough, even if it was not perfect?","body":"A small choice counts. If none comes to mind, describe a task you handled.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note what information you had when choosing, without using later knowledge.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5bdce078-2312-7a4b-2b96-3d591ca66cbb', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 5, 'Hear your own judgment', 'What did you do that helped in that situation?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What did you do that helped in that situation?","body":"Choose any that fit. You can also pick none.","elara":"That helps. You can change it any time.","config":{"optional":true,"maxSelections":6,"options":["Asked","Prepared","Adapted","Asked for help","Used what I knew","Something else"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep one concrete behavior you can repeat.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '386dd426-42b6-0415-a477-f302b8579d85', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 6, 'Hear your own judgment', 'What small preference could you express without overexplaining it?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What small preference could you express without overexplaining it?","body":"Rehearse “I prefer ___.” You can keep it private.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Prepare a preference sentence; saying it aloud is optional.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
