INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'da234079-80fc-3507-7d8f-3195bdd9b518', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 8, 'Your voice among others', 'Whose opinion tends to carry the most weight in your decisions?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a personal criterion with context, without unfair comparison.","weekTitle":"Your voice among others","intro":{"title":"Your voice among others","note":"Week 2: Your voice among others. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"Whose opinion tends to carry the most weight in your decisions?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["Someone close","An authority","People online","My own expectation","It depends","Another source"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Identify whether that opinion brings relevant experience to this decision.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
