INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '144c3359-4557-7381-ab44-c141a7727b34', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 15, 'Keep a small promise', 'What commitment to yourself would genuinely be small this week?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a realistic commitment and a nonpunitive adjustment.","weekTitle":"Keep a small promise","intro":{"title":"Keep a small promise","note":"Week 3: Keep a small promise. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What commitment to yourself would genuinely be small this week?","body":"Something mainly within your control; choosing none is valid.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Define a small result within your control, or choose not to commit.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
