INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b6cfc82b-3cab-ca7c-1590-5ffd5da1c2f5', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 17, 'Keep a small promise', 'What minimum version would still matter to you?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What minimum version would still matter to you?","body":"Smaller does not mean meaningless. It can be one step.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write the minimum version with a clear beginning and end.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
