INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'be89f063-9470-f243-26f1-1ddbb5a026c4', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 19, 'Keep a small promise', 'What happened with the commitment you chose?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What happened with the commitment you chose?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Done","Partly","Changed it","Not possible","Chose not to","Chose none"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Record what happened without turning it into a label about yourself.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
