INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '503714f1-d5fd-fcc0-46e5-5c83e76343b8', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 21, 'Keep a small promise', 'If the commitment did not go as hoped, what adjustment would be fairer than blaming yourself?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Choose without total certainty","letter":"This week was about “Keep a small promise”. What you wrote to keep: “{d21.ask}”. It is yours to reuse, change or leave. Next week: Choose without total certainty.","letterFallback":"This week was about “Keep a small promise”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Choose without total certainty."}', NULL, '[{"id":"ask","kind":"reflect","title":"If the commitment did not go as hoped, what adjustment would be fairer than blaming yourself?","body":"Include conditions that helped or were missing.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep one condition that helped or that you would need next time.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e1754ed3-b61b-d683-c4f2-901ebbe1919a', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 22, 'Choose without total certainty', 'What decision are you postponing while waiting to feel completely certain?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a revisable everyday decision.","weekTitle":"Choose without total certainty","intro":{"title":"Choose without total certainty","note":"Week 4: Choose without total certainty. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What decision are you postponing while waiting to feel completely certain?","body":"Choose a small reversible decision, not a high-stakes one.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Limit the exercise to an everyday decision you can revisit.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '202e826e-47af-15d8-cb19-8aace8ef5421', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 23, 'Choose without total certainty', 'What information would be enough to decide that small matter?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"What information would be enough to decide that small matter?","body":"Up to three facts. Distinguish necessary from nice to know.","elara":"That helps. You can change it any time.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Fact 1","Fact 2","Fact 3"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark which fact is actually missing.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ad9892c0-13a9-02d5-abbe-de0c569c27a0', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 24, 'Choose without total certainty', 'Which part of that decision could you change later?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which part of that decision could you change later?","body":"If not reversible, choose another small decision for this exercise.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note how you could revisit the choice without promising there will be no inconvenience.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7d98a28d-69ca-0fd0-6282-3b6d1510d9f6', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 25, 'Choose without total certainty', 'What would help you choose between two good-enough options?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What would help you choose between two good-enough options?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["My preference","Effort","Time","Cost","Ability to change later","Another criterion"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose one main criterion instead of requiring one option to win on everything.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '734ce4c7-4b3d-d9b5-006c-5d37394cf8a3', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 26, 'Choose without total certainty', 'What would you choose now with the information you do have?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would you choose now with the information you do have?","body":"You can choose to wait and name missing information; no action required today.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write a clear provisional decision or remaining question.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1a57eb81-7d66-959d-f33b-ee3136cbc166', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 27, 'Choose without total certainty', 'What happened after choosing, or what still prevents a decision?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What happened after choosing, or what still prevents a decision?","body":"Separate the outcome from the decision given what you knew.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note one thing within your control and one outside it.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '15cbfd49-8e49-dadb-bcef-ee89eea4b35f', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 28, 'Choose without total certainty', 'What would you like to remember about deciding without total certainty?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Return to trust","letter":"This week was about “Choose without total certainty”. What you wrote to keep: “{d28.ask}”. It is yours to reuse, change or leave. Next week: Return to trust.","letterFallback":"This week was about “Choose without total certainty”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Return to trust."}', NULL, '[{"id":"ask","kind":"reflect","title":"What would you like to remember about deciding without total certainty?","body":"Base it on your experience, not a rule for every decision.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep an observation for small decisions, not for every risk.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a90f1b9e-279b-5839-1c87-46670760878d', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 29, 'Return to trust', 'Think of a small mistake that still weighs on you, if any. What conclusion about yourself did you draw from it?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a possible repair and a fact-based note.","weekTitle":"Return to trust","intro":{"title":"Return to trust","note":"Week 5: Return to trust. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"Think of a small mistake that still weighs on you, if any. What conclusion about yourself did you draw from it?","body":"Use an everyday example or skip.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Describe the mistake as a concrete event without “always” or “I am.”","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'be1db555-9841-3281-35e8-e8e829a0af02', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 30, 'Return to trust', 'What responsibility is yours, and what part was outside your control?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"What responsibility is yours, and what part was outside your control?","body":"Recognizing context does not erase what you can repair.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["My responsibility","Outside my control"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose one specific responsibility without taking on someone else''s part.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e8c4827d-9493-0acc-9800-549df5942249', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 31, 'Return to trust', 'Is there something concrete to repair or learn from that mistake without turning it into a verdict about yourself?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Is there something concrete to repair or learn from that mistake without turning it into a verdict about yourself?","body":"If nothing needs repair, name a lesson or leave it here.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Leave a possible repair or concrete lesson; punishment is not required to remember it.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '788ab8a7-a212-7437-5641-b8bfbe374a8c', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 32, 'Return to trust', 'What would you ask a trusted person without handing over the whole decision?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would you ask a trusted person without handing over the whole decision?","body":"Draft: “Help me think through ___; I want to choose.” No contact required.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Prepare a request for perspective that preserves your right to decide.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ffa9df69-ac1c-064e-2cfe-ce64772859a3', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 33, 'Return to trust', 'What sentence would help when you seek permission for a small choice again?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What sentence would help when you seek permission for a small choice again?","body":"Say a sentence you can believe.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Adjust the sentence until it feels believable, even if modest.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '96046715-9586-bfdc-4cc8-9f850345ffef', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 34, 'Return to trust', 'What recent choice or adjustment shows that you can listen to yourself?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What recent choice or adjustment shows that you can listen to yourself?","body":"Asking for help, changing your mind or admitting uncertainty counts.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Add that example to your personal evidence list.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5f03df98-d78b-3968-e80c-ff7e28c5464c', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'en'), 35, 'Return to trust', 'What belongs in a self-trust note grounded in facts?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"This week was about “Return to trust”. What you wrote to keep: “{d35.ask}”. It is yours to reuse, change or leave. That is the whole path. Any day is there if you want to come back to it.","letterFallback":"This week was about “Return to trust”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. That is the whole path. Any day is there if you want to come back to it."}', NULL, '[{"id":"ask","kind":"blanks","title":"What belongs in a self-trust note grounded in facts?","body":"Complete only the lines you want.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["I have managed…","It helps when…","When I doubt, I can…"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep two facts and one resource you can return to when uncertain.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('0e073012-ec5a-8cba-c494-8144a506a0e9', 'energy', 'en', 'ENERGY', 'Energy Reset', 'Energy Reset', 'solar:fire-bold-duotone', '#EC7A4E', 'Restore your natural reserves, sustainably.', 2, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '37ef85a3-1feb-8e58-aa14-8e8b8544d438', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 1, 'Notice without diagnosing', 'When recently did you feel you had no capacity left?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: provisional observations about loads and needs.","weekTitle":"Notice without diagnosing","intro":{"title":"Notice without diagnosing","note":"Week 1: Notice without diagnosing. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"When recently did you feel you had no capacity left?","body":"It may be physical, mental, or social; you do not have to explain a cause.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Describe the moment without turning it into an explanation of who you are.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1761b5be-38ee-1980-23df-7fd6129e8709', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 2, 'Notice without diagnosing', 'What kind of load do you notice most today?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What kind of load do you notice most today?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["Physical","Mental","Emotional","Social","Several","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name one demand related to that load without diagnosing its cause.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f5623b38-a81e-7643-3d6c-ce5b14aebea4', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 3, 'Notice without diagnosing', 'What was happening just before you noticed that tiredness?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"What was happening just before you noticed that tiredness?","body":"Up to three facts, without seeking a diagnosis.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Fact 1","Fact 2","Fact 3"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Separate facts from explanations you do not yet know are true.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5cceb446-1c00-6c2c-148d-182fbe81b5e5', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 4, 'Notice without diagnosing', 'Draw how your energy varied yesterday. What change did you notice, if any?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Draw how your energy varied yesterday. What change did you notice, if any?","body":"A line or words; no score needed.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark one change to observe another day; a single day does not prove a pattern.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'da45bf43-ed80-3ce8-d7b0-63295d022f32', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 5, 'Notice without diagnosing', 'What moment gave you a little more space, even if it did not make you feel happy?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What moment gave you a little more space, even if it did not make you feel happy?","body":"If none did, write what might have reduced one demand.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the detail or demand that would have been useful to reduce.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0c10b5e2-9c23-8695-21c6-f4e7d54059b7', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 6, 'Notice without diagnosing', 'What do you need first when you feel like this?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What do you need first when you feel like this?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Less stimulation","A basic need","Company","Time alone","Help with a load","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Define a small way to address that need, or the help missing.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '853e3f75-ac13-bc67-51d2-06f19992c357', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 7, 'Notice without diagnosing', 'What observation about your energy is worth remembering without turning it into a rule?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Rest that fits","letter":"This week was about “Notice without diagnosing”. What you wrote to keep: “{d7.ask}”. It is yours to reuse, change or leave. Next week: Rest that fits.","letterFallback":"This week was about “Notice without diagnosing”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Rest that fits."}', NULL, '[{"id":"ask","kind":"reflect","title":"What observation about your energy is worth remembering without turning it into a rule?","body":"Complete: “This week I noticed…”. One week does not define your body.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the observation as provisional, not a fixed label.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f6ce619b-d5a5-1b3d-ba3d-7e4d69c48c01', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 8, 'Rest that fits', 'What do you do to rest that sometimes ends up feeling like another obligation?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a tested pause or the barrier preventing it.","weekTitle":"Rest that fits","intro":{"title":"Rest that fits","note":"Week 2: Rest that fits. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What do you do to rest that sometimes ends up feeling like another obligation?","body":"If this does not happen, describe rest that works for you.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Remove one demand from your current idea of rest.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
