INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7ea5b74d-a732-bf77-1fe2-5d85e7c29d98', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 10, 'Rest that fits', 'What kind of pause would you like to try today, if you have room?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What kind of pause would you like to try today, if you have room?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Quiet","Change position","Look outside","Something pleasant with no goal","Ask someone to take over","I cannot today"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If useful, try a brief pause without requiring yourself to finish it or feel better.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7f4ec4ca-a77e-ce20-619e-b1492c3c4d04', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 11, 'Rest that fits', 'What makes it difficult to take that pause?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What makes it difficult to take that pause?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["No time","No one can take over","I feel guilty","No space","Unsure what helps","Another reason"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note one concrete barrier instead of attributing everything to willpower.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b48317ca-b702-ab18-552a-d9424ed97a16', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 12, 'Rest that fits', 'If you took a pause, how did you feel afterward compared with before?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"If you took a pause, how did you feel afterward compared with before?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["More capacity","Same","Less capacity","Mixed","Did not pause","Cannot tell"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Record the effect without grading yourself or persisting with something uncomfortable.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
