INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '982f4638-e435-e3e5-47bb-fa9de4cf18ae', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 17, 'Reduce what drains', 'What sentence would give you time to check your capacity before agreeing?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What sentence would give you time to check your capacity before agreeing?","body":"Draft: “I''ll check and confirm…”. Choose a realistic timeframe.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the sentence to use only when appropriate and safe.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b8198010-6e5b-9a03-5d80-d4f8138f084e', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 18, 'Reduce what drains', 'What part of your surroundings adds a load you barely notice until it disappears?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What part of your surroundings adds a load you barely notice until it disappears?","body":"Choose any that fit. You can also pick none.","elara":"Noted. Nothing here has to be perfect.","config":{"exclusiveOption":5,"optional":true,"maxSelections":6,"options":["Noise","Notifications","Visual clutter","Lack of privacy","Interruptions","None of these"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose one stimulus you can reduce without losing something necessary.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0c17c737-cf15-3155-ee79-0580dc28668d', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 19, 'Reduce what drains', 'What small change to your surroundings could you try without buying anything?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"What small change to your surroundings could you try without buying anything?","body":"Optional photo of a detail without personal information, or describe it. No beautiful setting required.","elara":"Thank you. That is enough to work with.","config":{"quiet":true,"optional":true,"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Try a reversible change if within reach, or leave the plan in text.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'de12b90c-f238-edd6-8130-5d115c122a92', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 20, 'Reduce what drains', 'What load needs support rather than another individual strategy?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What load needs support rather than another individual strategy?","body":"Name the practical help; you do not have to know who can provide it yet.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Turn the load into a concrete request or an unresolved support need.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '730d7303-34eb-f5b2-6cc1-284f4db5d0f9', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 21, 'Reduce what drains', 'What demand do you want to reduce, share, or recognize as unavoidable for now?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Curiosity without performance","letter":"This week was about “Reduce what drains”. What you wrote to keep: “{d21.ask}”. It is yours to reuse, change or leave. Next week: Curiosity without performance.","letterFallback":"This week was about “Reduce what drains”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Curiosity without performance."}', NULL, '[{"id":"ask","kind":"reflect","title":"What demand do you want to reduce, share, or recognize as unavoidable for now?","body":"Choose one. Recognizing a real limitation also provides clarity.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Record a decision about that demand, even if “I need help first.”","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
