INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '973173c0-f508-cd4b-6b6e-d8a968af621c', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 24, 'Curiosity without performance', 'What enjoyment have you left out because it seemed unproductive?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What enjoyment have you left out because it seemed unproductive?","body":"If none, name something you already enjoy and want to keep.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name what that enjoyment means to you, even if it produces nothing.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '07232917-444a-3835-fca2-193a90e0de0c', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 25, 'Curiosity without performance', 'What would be an accessible version of that enjoyment in your current situation?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would be an accessible version of that enjoyment in your current situation?","body":"No purchases, travel, or requirement to feel better afterward.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep a possible version requiring no spending or travel.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '228d1cd6-f670-d159-3a84-e683ecc24bf9', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 26, 'Curiosity without performance', 'What happened when you engaged with something that interests you, if you did?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What happened when you engaged with something that interests you, if you did?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["Made me curious","Felt calming","Nothing changed","Tired me","Mixed feelings","Did not do it"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note the effect as it was; “nothing changed” is also informative.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '852e5fcc-6ed6-8f79-9f39-7d9e0a6de4ad', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 27, 'Curiosity without performance', 'What is the difference for you between a little distraction and feeling renewed?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What is the difference for you between a little distraction and feeling renewed?","body":"You do not have to label one good and the other bad. Use an example.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep one useful distinction for choosing based on what you need.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '77b70ed1-ed12-6927-053e-5948ed344d50', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 28, 'Curiosity without performance', 'What possibility for enjoyment would you like to keep available for another day?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Protect your capacity","letter":"This week was about “Curiosity without performance”. What you wrote to keep: “{d28.ask}”. It is yours to reuse, change or leave. Next week: Protect your capacity.","letterFallback":"This week was about “Curiosity without performance”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Protect your capacity."}', NULL, '[{"id":"ask","kind":"reflect","title":"What possibility for enjoyment would you like to keep available for another day?","body":"Keep a brief idea without committing to doing it.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Add the idea to an optional list without a deadline.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5a8beb0e-946d-2d2b-d080-c77f50079b79', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 29, 'Protect your capacity', 'What signs would you like to notice before reaching your limit?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a practical note for low-energy days.","weekTitle":"Protect your capacity","intro":{"title":"Protect your capacity","note":"Week 5: Protect your capacity. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"blanks","title":"What signs would you like to notice before reaching your limit?","body":"Up to three personal signs; these are not for diagnosis.","elara":"That helps. You can change it any time.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Sign 1","Sign 2","Sign 3"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Pair one sign with a small response within your reach.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a7c1fa63-9075-3687-89b8-f9ada9b3bf9f', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 30, 'Protect your capacity', 'What could you remove from a low-energy day without neglecting an essential need?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What could you remove from a low-energy day without neglecting an essential need?","body":"If nothing can be removed, name the help that is missing.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write a lighter version of the day or the support needed to make it possible.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'cf101175-2809-6be6-78e6-096dcfbb0af1', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 31, 'Protect your capacity', 'What tends to help, and what did not help even though it sounded like good advice?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"What tends to help, and what did not help even though it sounded like good advice?","elara":"Thank you. That is enough to work with.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Helps me","Does not help me for now"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep both lists; something unhelpful need not become an obligation.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'acad9421-e93a-607a-78c3-a91a10435a20', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 32, 'Protect your capacity', 'How would you explain to someone you trust what support you need on a difficult day?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"How would you explain to someone you trust what support you need on a difficult day?","body":"One concrete request, with no obligation to send it.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the request ready while protecting details you do not want to share.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '90a70a6d-0c02-2307-2af9-572848bb4b81', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 33, 'Protect your capacity', 'What would you like to remember when you have energy to do more?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would you like to remember when you have energy to do more?","body":"It might be not committing all your capacity for the coming days.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note some capacity you want to reserve before accepting more commitments.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '52a6a60a-936b-dd1d-ba9f-993682f70b17', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 34, 'Protect your capacity', 'What pattern is worth continuing to observe, and what remains uncertain?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What pattern is worth continuing to observe, and what remains uncertain?","body":"No need to explain why it occurs or draw medical conclusions.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Separate observation from uncertainty; this note alone does not explain a health problem.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '05aacd61-b1ac-c848-238a-9b2cecad0998', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'en'), 35, 'Protect your capacity', 'What practical note would you leave for yourself on a low-energy day?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"This week was about “Protect your capacity”. What you wrote to keep: “{d35.ask}”. It is yours to reuse, change or leave. That is the whole path. Any day is there if you want to come back to it.","letterFallback":"This week was about “Protect your capacity”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. That is the whole path. Any day is there if you want to come back to it."}', NULL, '[{"id":"ask","kind":"blanks","title":"What practical note would you leave for yourself on a low-energy day?","body":"Complete only the lines you want.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["I can simplify…","It helps me to…","I can ask for…"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Check that the note is short and useful even when you do not want to write more.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('a7b00207-a08c-1d52-5fef-efaa116e50f7', 'purpose', 'en', 'PURPOSE', 'Purpose Finding', 'Purpose Finding', 'solar:case-bold-duotone', '#7C6BA8', 'Reconnect with what actually drives you.', 3, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e888cf79-6628-ade9-47ff-2c6c3aa6b01f', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 1, 'A question of your own', 'What keeps returning to your mind when you finally have a moment to yourself?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a small focus that can be explored.","weekTitle":"A question of your own","intro":{"title":"A question of your own","note":"Week 1: A question of your own. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What keeps returning to your mind when you finally have a moment to yourself?","body":"Describe one situation, not your whole story.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Give the recurring topic a short title.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ef491fc0-e4d2-b8f2-2355-fa6ade3cab3a', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 2, 'A question of your own', 'What fills your week and leaves little room for something that matters to you?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What fills your week and leaves little room for something that matters to you?","body":"Name a specific tension without assuming you can remove the obligation.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Identify whether time, support, or your own permission is missing; no solution required today.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9a8fb5a3-03c4-be45-aca4-ffbdccda1e9c', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 3, 'A question of your own', 'What could you look at for five minutes to understand a curiosity?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What could you look at for five minutes to understand a curiosity?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["A course","Job duties","Someone''s project","A local activity","Something else","Nothing today"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If possible, look at one source for five minutes and note something you did not know.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c1f08fb8-6765-4822-fc59-7869bbfef808', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 4, 'A question of your own', 'Which part of what you feel you should want would you choose yourself?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which part of what you feel you should want would you choose yourself?","body":"If no pressure fits, describe an interest you need not justify.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Underline one preference you recognize as your own.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '731aa2b0-448a-ecc9-f6ca-17bffca3947d', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 5, 'A question of your own', 'What made a recent moment worth repeating?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What made a recent moment worth repeating?","body":"Choose any that fit. You can also pick none.","elara":"That helps. You can change it any time.","config":{"optional":true,"maxSelections":6,"options":["Calm","Connection","Learning","Making or solving","Enjoyment","Something else"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note one concrete condition that made that moment possible.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c386c0db-24b0-aea2-d65c-e512620abba8', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 6, 'A question of your own', 'What one thing do you want to understand without deciding your future yet?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What one thing do you want to understand without deciding your future yet?","body":"Make it concrete: “Whether this course fits,” not “What to do with my life.”","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write your focus as a question you could investigate.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6c89d953-cc92-65aa-4ee7-0eac3f704b8a', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 7, 'A question of your own', 'What discovery from these days do you want to keep?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"What your life needs","letter":"This week was about “A question of your own”. What you wrote to keep: “{d7.ask}”. It is yours to reuse, change or leave. Next week: What your life needs.","letterFallback":"This week was about “A question of your own”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: What your life needs."}', NULL, '[{"id":"ask","kind":"reflect","title":"What discovery from these days do you want to keep?","body":"A curiosity, preference or clearer question.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep one finding and one question without having to resolve it.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6fcb9c7e-6545-9344-fea2-319f4d152151', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 8, 'What your life needs', 'What works in your life that you would not want to lose through a change?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: up to three conditions for comparing options.","weekTitle":"What your life needs","intro":{"title":"What your life needs","note":"Week 2: What your life needs. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What works in your life that you would not want to lose through a change?","body":"A real condition: a relationship, income, schedule or personal time.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name one thing you do not want to sacrifice while exploring.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '51e84b1f-6357-8ccf-7a74-9f3bf4245cb5', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 9, 'What your life needs', 'Which condition most needs protecting in the change you imagine?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"Which condition most needs protecting in the change you imagine?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Basic income","Caring responsibilities","Time and energy","Where I live","A commitment","Another condition"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Turn the chosen condition into a filter for future options.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3366d97c-554c-210f-6144-3ccb30d877de', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 10, 'What your life needs', 'What would make this easier to explore without changing everything at once?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would make this easier to explore without changing everything at once?","body":"One source of help, fact or smaller version.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Draft the help or information you would request.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '044b0765-5f69-87c1-76ba-f6efacdf3a7e', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 11, 'What your life needs', 'Which of your conditions might be flexible, if any?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which of your conditions might be flexible, if any?","body":"Separate “I would prefer” from “I need.” None may be flexible now.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark a condition as necessary and another as preferred, only if that distinction exists.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '13d090d4-c8ba-37ce-9453-0678da44366d', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 12, 'What your life needs', 'How much room do you actually have to explore right now?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"How much room do you actually have to explore right now?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Five minutes","Some time this week","Regular time","Just looking","None for now","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Match the next attempt to your actual capacity; zero is also an answer.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b6dbae37-f68f-33fb-9751-9f36a97eecb6', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 13, 'What your life needs', 'Which two things you want seem difficult to have at the same time?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which two things you want seem difficult to have at the same time?","body":"Draw two circles and label what matters in each. You can write two sentences instead.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Identify what each wish protects before trying to choose between them.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '618617c4-f23b-b4bd-28a6-97add90b7624', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 14, 'What your life needs', 'Which three things would an option need to protect to fit your life?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Look at possibilities","letter":"This week was about “What your life needs”. What you wrote to keep: “{d14.ask}”. It is yours to reuse, change or leave. Next week: Look at possibilities.","letterFallback":"This week was about “What your life needs”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Look at possibilities."}', NULL, '[{"id":"ask","kind":"blanks","title":"Which three things would an option need to protect to fit your life?","body":"Up to three conditions; no need to rank them or resolve conflicts.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["Condition 1","Condition 2","Condition 3"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the conditions as a comparison list, not a test.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
