INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '03a4765c-386f-be99-c930-77a686a44fcd', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 16, 'Look at possibilities', 'What would an ordinary Tuesday look like in one of those options?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would an ordinary Tuesday look like in one of those options?","body":"Include an everyday task, not only the ideal moment.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Add an unglamorous task that would also be part of that option.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
