INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c079d66d-9e85-886a-e104-f88e2d2bec62', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 26, 'Try to learn', 'What happened with the attempt you chose?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What happened with the attempt you chose?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["I did it","Partly","Not yet","Changed it","Set it aside","Did not choose one"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Record the status without turning it into a performance grade.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '40fd35d4-aea5-56fa-9fba-8188a64b9312', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 27, 'Try to learn', 'What surprised you, or what barrier do you need to account for?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What surprised you, or what barrier do you need to account for?","body":"Describe events without judging your ability.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note one fact that changes how you would approach another attempt.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2a868b86-21d8-a9ee-5733-62f5f9b070e2', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 28, 'Try to learn', 'What do you know now, and what remains open?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"A direction for now","letter":"This week was about “Try to learn”. What you wrote to keep: “{d28.ask}”. It is yours to reuse, change or leave. Next week: A direction for now.","letterFallback":"This week was about “Try to learn”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: A direction for now."}', NULL, '[{"id":"ask","kind":"blanks","title":"What do you know now, and what remains open?","body":"Completion of the attempt is not required.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["What I know now","What remains open"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Separate learning and the remaining question in your note.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1036c396-58bd-6b32-5aa4-408d7c323e7e', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 29, 'A direction for now', 'Is what you want to understand still the same?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a provisional decision, including pausing.","weekTitle":"A direction for now","intro":{"title":"A direction for now","note":"Week 5: A direction for now. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"Is what you want to understand still the same?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["Yes","Refine it","Changed substantially","No longer interested","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If your focus changed, write the new version in one sentence.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1e06f240-bb9d-956a-52c5-64f7627f1eb1', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 30, 'A direction for now', 'Which personal condition became clearer through exploring?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which personal condition became clearer through exploring?","body":"It may be confirmed, changed or still unresolved.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Update one condition on your list; keeping it unchanged is fine.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'beae4b5d-93a9-e407-2ccb-16579607e59d', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 31, 'A direction for now', 'Which direction fits your next stage?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"Which direction fits your next stage?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Keep exploring","Take a concrete step","Explore another option","Stay as I am","Set it aside","Not choose yet"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name your provisional choice, including pausing.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a8635b8b-ea2c-032a-cbd9-035797ae296e', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 32, 'A direction for now', 'What would that decision look like during an ordinary week?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would that decision look like during an ordinary week?","body":"If you chose to stop, describe what you will stop requiring of yourself for now.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Describe an everyday action compatible with that decision, or what you will stop doing.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'daed1716-81b0-140c-23aa-4e34252aed1f', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 33, 'A direction for now', 'What support is missing, and what part is possible without it?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What support is missing, and what part is possible without it?","body":"“Nothing without that support” is valid; do not turn a real barrier into a demand.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Distinguish a possible step from one that requires support first.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3bca0603-cba7-e769-df33-8e2b03cc6e43', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 34, 'A direction for now', 'What would tell you it is time to revisit your decision?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would tell you it is time to revisit your decision?","body":"A schedule change, new information or your chosen date. No automatic reminder.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note the review signal without treating it as a deadline.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'abe0a64c-c4a2-1291-02ae-677aec794946', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'en'), 35, 'A direction for now', 'What note would you like to leave yourself about your direction for now?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"This week was about “A direction for now”. What you wrote to keep: “{d35.ask}”. It is yours to reuse, change or leave. That is the whole path. Any day is there if you want to come back to it.","letterFallback":"This week was about “A direction for now”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. That is the whole path. Any day is there if you want to come back to it."}', NULL, '[{"id":"ask","kind":"blanks","title":"What note would you like to leave yourself about your direction for now?","body":"Complete only the lines you want.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["I care about…","I need to protect…","I choose…","I can revisit when…"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Reread the note: it should reflect your current life, not justify it to anyone.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('dbe33db8-af7d-8387-6e04-7b7763a4c7ce', 'love', 'en', 'LOVE', 'Love & Boundaries', 'Love & Boundaries', 'solar:heart-bold-duotone', '#C2657E', 'See your relationship patterns clearly and choose how you show up.', 4, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3b01da02-f266-69fc-a66c-2bb325b7089d', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 1, 'Recognize what you need', 'In which relationship would you like to feel a little more like yourself this week?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a need translated into a concrete request.","weekTitle":"Recognize what you need","intro":{"title":"Recognize what you need","note":"Week 1: Recognize what you need. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"In which relationship would you like to feel a little more like yourself this week?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Partner","Family","Friendship","People at work","Other","Prefer not to choose"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose one relationship to observe this week without needing to change it.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9fffeff5-7158-e87b-381e-f67f959f8071', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 2, 'Recognize what you need', 'Think of a recent moment when you felt heard. What did the other person do that helped?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Think of a recent moment when you felt heard. What did the other person do that helped?","body":"A small detail counts; if none comes to mind, describe how you would like to be heard.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name the behavior that helped: listening, asking, or giving time, for example.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ff09f957-dca1-5385-d227-3923263a2055', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 3, 'Recognize what you need', 'When did you say “it''s okay” while needing something different inside?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"When did you say “it''s okay” while needing something different inside?","body":"One everyday situation, without names. “That did not happen this week” is valid.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Translate that “it''s okay” into a private need; if irrelevant, keep a hypothetical example.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd9a26b2d-d4f2-7e2f-6cb4-e93ffc6908c4', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 4, 'Recognize what you need', 'What do you most need from that relationship now?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What do you most need from that relationship now?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Time together","Space","Clarity","Practical help","Respect for a boundary","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Complete “It would help me…” with a concrete action.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '786c28cd-1729-8cde-7a40-1882ccf013c7', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 5, 'Recognize what you need', 'What would that need look like as an action another person could understand?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would that need look like as an action another person could understand?","body":"Example: “Tell me if you will be late,” rather than “Consider me.”","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Check that your request says what you need without requiring mind-reading.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '82a67894-b4bb-5233-a751-0cd81ad3f991', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 6, 'Recognize what you need', 'Draw two spaces: the time you share now and the time you would like for yourself. What would you change?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Draw two spaces: the time you share now and the time you would like for yourself. What would you change?","body":"They need not be equal or measured. You can describe them in words.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark one space you want to reserve; no justification or negotiation needed today.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'bab04874-b8a0-1bfc-d905-33bd324733d1', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 7, 'Recognize what you need', 'What need would you like to stop minimizing, even if you do not yet know how to ask for it?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Boundaries you can name","letter":"This week was about “Recognize what you need”. What you wrote to keep: “{d7.ask}”. It is yours to reuse, change or leave. Next week: Boundaries you can name.","letterFallback":"This week was about “Recognize what you need”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Boundaries you can name."}', NULL, '[{"id":"ask","kind":"reflect","title":"What need would you like to stop minimizing, even if you do not yet know how to ask for it?","body":"Complete: “It also matters to me that…” You do not have to share it.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the sentence as a reference for a future conversation.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0b3b5d5b-f99d-3606-453e-5bda747f6e2c', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 8, 'Boundaries you can name', 'What recent request made you think “I don''t want to, but I should”?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a boundary draft and a safe option.","weekTitle":"Boundaries you can name","intro":{"title":"Boundaries you can name","note":"Week 2: Boundaries you can name. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What recent request made you think “I don''t want to, but I should”?","body":"If none occurred, choose a small hypothetical request.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write what you want to answer before thinking about pleasing others.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '53683c15-d42c-4a55-0c64-68ed321949e4', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 9, 'Boundaries you can name', 'What makes saying no difficult in that situation?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What makes saying no difficult in that situation?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Fear of disappointing","I need their help","I lack the words","Fear of a reaction","I want to but cannot","Another reason"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If you fear a reaction, keep the exercise private and prioritize support; do not rehearse confrontation.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '50d4c79e-d3e2-9bc8-b12b-d6b62cfdf449', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 10, 'Boundaries you can name', 'What can you offer without promising something you do not want to sustain?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What can you offer without promising something you do not want to sustain?","body":"It is also valid not to offer an alternative.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Distinguish an alternative you want to offer from one offered out of obligation.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '11cad125-4796-7685-0e1b-a925303163df', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 11, 'Boundaries you can name', 'What would a short boundary sound like without explaining your whole history?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would a short boundary sound like without explaining your whole history?","body":"Private draft: “Today I can''t…” or “I can…, but not…”. No need to send it.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Reduce the draft to one or two clear sentences.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'cb4acd7a-a357-9971-5452-c1b1466b8f4f', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 12, 'Boundaries you can name', 'If they insist, what sentence could you repeat without entering an argument?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"If they insist, what sentence could you repeat without entering an argument?","body":"Rehearse only if it feels safe. You may choose not to respond.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep a repeatable sentence or an option not to respond.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2a7a44e5-5fb1-7b98-071c-bd542dc3b033', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 13, 'Boundaries you can name', 'Which option best supports you in this specific situation?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"Which option best supports you in this specific situation?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["Ask for time","Say no","Negotiate part","Ask for support","Do not respond for now","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name the safest next step, even if it is waiting.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '79c760f1-e778-3723-0c64-2dfff68cda2c', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 14, 'Boundaries you can name', 'What did you learn by drafting the boundary, even if you did not say it?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Make room for connection","letter":"This week was about “Boundaries you can name”. What you wrote to keep: “{d14.ask}”. It is yours to reuse, change or leave. Next week: Make room for connection.","letterFallback":"This week was about “Boundaries you can name”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Make room for connection."}', NULL, '[{"id":"ask","kind":"reflect","title":"What did you learn by drafting the boundary, even if you did not say it?","body":"It may be clarity, discomfort, or needing support before acting.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note what support you would need before saying it, if you want to.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '91a0ae9a-5806-8650-79dc-f394539b0ea6', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 15, 'Make room for connection', 'What kind of company do you miss beyond simply “having people”?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a possible invitation without pressure or exposure.","weekTitle":"Make room for connection","intro":{"title":"Make room for connection","note":"Week 3: Make room for connection. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"What kind of company do you miss beyond simply “having people”?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Unhurried conversation","Doing something together","Laughing","Feeling understood","Everyday help","I do not miss company now"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Turn your chosen kind of company into one small possible activity.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4a4d275a-958e-5262-9534-a60b7b719498', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 16, 'Make room for connection', 'With whom could you have a small connection without telling them everything?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"With whom could you have a small connection without telling them everything?","body":"Use an initial or describe a setting; no name needed.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose a contact or setting that respects your privacy; reaching out remains optional.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7bf095e7-59be-3a6f-483b-1421d76c6061', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 17, 'Make room for connection', 'What invitation would be easy to accept or decline without pressure?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What invitation would be easy to accept or decline without pressure?","body":"Draft an activity with room to decline: “Would you like to…? No worries if you can''t.”","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the invitation ready, without pressure or obligation to send it.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7ccb5291-df75-5e00-79c6-17c8d994c83e', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 18, 'Make room for connection', 'What would help you be present in a brief conversation?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What would help you be present in a brief conversation?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Put away my phone","Choose a calm moment","State my time limit","Listen without fixing","Ask to be heard","Something else"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose just one condition for your next conversation.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f799340a-3fa9-57b6-bfaf-415b72d30ab2', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 19, 'Make room for connection', 'What would you ask to understand their experience without immediately offering advice?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would you ask to understand their experience without immediately offering advice?","body":"Write one question that does not assume how they feel.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the question and leave room to hear the answer.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '45492bd7-afbe-74c0-a41e-4dbe1621a727', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 20, 'Make room for connection', 'How did your attempt to connect go, if you made one?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"How did your attempt to connect go, if you made one?","body":"Choose one.","elara":"That helps. You can change it any time.","config":{"optional":true,"options":["We connected","Still pending","They could not","It did not feel good","I did not try","I chose time alone"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Record what happened without treating silence as certain rejection.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2ad162bb-05cc-43b9-e5d0-953dd01965de', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 21, 'Make room for connection', 'What gesture of connection would you like to repeat, adapt, or leave behind?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Care within disagreement","letter":"This week was about “Make room for connection”. What you wrote to keep: “{d21.ask}”. It is yours to reuse, change or leave. Next week: Care within disagreement.","letterFallback":"This week was about “Make room for connection”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Care within disagreement."}', NULL, '[{"id":"ask","kind":"reflect","title":"What gesture of connection would you like to repeat, adapt, or leave behind?","body":"Someone else''s response does not measure your worth. Choose based on how it fits your life.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose to repeat, adapt, or release the gesture based on your experience.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '252ac378-e50d-8578-15f1-60ef8cfd3cf7', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 22, 'Care within disagreement', 'In a small disagreement, what happened and what interpretation did you add?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: separate facts, responsibility, and conditions for talking.","weekTitle":"Care within disagreement","intro":{"title":"Care within disagreement","note":"Week 4: Care within disagreement. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"blanks","title":"In a small disagreement, what happened and what interpretation did you add?","body":"An invented example is fine.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["What I observed","What I assumed"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark one interpretation that needs clarification before treating it as fact.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a2623485-0ae4-3d83-9a99-86643f729b32', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 23, 'Care within disagreement', 'What would you want the other person to understand without needing to win the argument?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What would you want the other person to understand without needing to win the argument?","body":"Choose one thing. You do not have to start that conversation.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Draft a sentence starting with what you observed and what you need.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a0cf4eb4-669d-50b0-e937-9f4cc95d46b0', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 24, 'Care within disagreement', 'What part, if any, is yours to repair?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What part, if any, is yours to repair?","body":"Separate your action from their reaction. “None” may be valid.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If appropriate, prepare a specific repair without taking all the blame.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'fe4a6f91-fe42-fc27-0963-17017b55f73a', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 25, 'Care within disagreement', 'How would you ask for a pause without promising to return before you are ready?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"How would you ask for a pause without promising to return before you are ready?","body":"Rehearse a private sentence. If speaking is unsafe, choose to seek support.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep a pause sentence that does not require an immediate resolution.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f3226ecd-14cb-3384-f8d2-d6378328e891', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 26, 'Care within disagreement', 'What sign would tell you this conversation can continue respectfully?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What sign would tell you this conversation can continue respectfully?","body":"Choose any that fit. You can also pick none.","elara":"That helps. You can change it any time.","config":{"exclusiveOption":4,"optional":true,"maxSelections":5,"options":["We can finish a sentence","No insults","A pause is respected","I can disagree","I do not see those conditions"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Identify one minimum condition for continuing; not talking may also be an option.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd7d3b2e6-cdee-0dc4-2e67-f32482414865', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 27, 'Care within disagreement', 'What would be useful to do with this disagreement for now?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What would be useful to do with this disagreement for now?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Clarify something","Repair my part","Let it rest","Seek support","Keep distance","Not decide yet"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name one step within your control without requiring the other person''s response.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'de122793-11d7-2d3b-e203-4eb3280c8d4d', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 28, 'Care within disagreement', 'What difference do you notice between caring for a relationship and taking responsibility for everything?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Sustainable relationships","letter":"This week was about “Care within disagreement”. What you wrote to keep: “{d28.ask}”. It is yours to reuse, change or leave. Next week: Sustainable relationships.","letterFallback":"This week was about “Care within disagreement”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Sustainable relationships."}', NULL, '[{"id":"ask","kind":"reflect","title":"What difference do you notice between caring for a relationship and taking responsibility for everything?","body":"Use a concrete example, real or imagined.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write one shared responsibility you do not want to carry alone.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '34f1dd1a-302b-8a69-d1a4-d22dba81f04a', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 29, 'Sustainable relationships', 'What small gesture has made you feel cared for in a way that reaches you?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a note on needs, support, and rhythm of contact.","weekTitle":"Sustainable relationships","intro":{"title":"Sustainable relationships","note":"Week 5: Sustainable relationships. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What small gesture has made you feel cared for in a way that reaches you?","body":"If none comes to mind, describe one you would like to receive.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the gesture as an example of care that reaches you.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'bd68b910-d725-15dd-7076-434b0720c6f2', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 30, 'Sustainable relationships', 'What could you ask for more clearly next time?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What could you ask for more clearly next time?","body":"Complete: “It would help me if…”. Sending it is optional.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Make the request concrete and leave room for an honest response.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'eb5c127b-c40d-5b15-4bac-494dff655a0a', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 31, 'Sustainable relationships', 'What support would you like to have beyond a single relationship?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What support would you like to have beyond a single relationship?","body":"Choose any that fit. You can also pick none.","elara":"Thank you. That is enough to work with.","config":{"exclusiveOption":5,"optional":true,"maxSelections":6,"options":["Friends","Chosen family","Community","Professional support","Time of my own","Not sure yet"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Name one additional support source or one you would like to find.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '745802fb-d3b1-526a-5b62-821c3a971dab', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 32, 'Sustainable relationships', 'What boundary remains important even when you are in a good mood?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What boundary remains important even when you are in a good mood?","body":"Write a sentence you would like to reread.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep the boundary without hardening it as punishment or withdrawing it from guilt.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ce4e9e6c-f858-745d-cae6-7c0347bf6029', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 33, 'Sustainable relationships', 'What rhythm of contact feels sustainable this season?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What rhythm of contact feels sustainable this season?","body":"It may be spontaneous, occasional, or agreed. Avoid promising a frequency out of guilt.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Describe a possible rhythm and a way to revisit it if circumstances change.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd7782cc9-8ce9-17a7-0c2d-45393445cc1f', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 34, 'Sustainable relationships', 'What do you now recognize about how you want to care and be cared for?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What do you now recognize about how you want to care and be cared for?","body":"Include one need and one possible action; neither has to sound polished.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Extract one sentence you would use in a real conversation, only if useful.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '22ec8c30-f3be-864d-bbf2-3863f7c3089c', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'en'), 35, 'Sustainable relationships', 'What would you like to carry from this path into your next relationship or conversation?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"This week was about “Sustainable relationships”. What you wrote to keep: “{d35.ask}”. It is yours to reuse, change or leave. That is the whole path. Any day is there if you want to come back to it.","letterFallback":"This week was about “Sustainable relationships”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. That is the whole path. Any day is there if you want to come back to it."}', NULL, '[{"id":"ask","kind":"blanks","title":"What would you like to carry from this path into your next relationship or conversation?","body":"Complete only the lines you want.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["I need…","I can ask…","I do not have to…"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Check that your note includes your needs and room to choose.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('674ad418-3910-b830-0949-cba9b80e09db', 'everyday', 'en', 'EVERYDAY', 'Daily Rhythm', 'Daily Rhythm', 'solar:armchair-bold-duotone', '#5E8B7E', 'Reduce the daily friction that quietly uses up your bandwidth.', 5, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f2797e5f-5b54-7c20-69e4-0c6ff184e3ff', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 1, 'See the real load', 'At what point in the day does everything seem to pile up?', NULL, 'reflect', '{"minutes":3,"payoff":"This week''s takeaway: a difficult moment described without self-blame.","weekTitle":"See the real load","intro":{"title":"See the real load","note":"Week 1: See the real load. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"choose","title":"At what point in the day does everything seem to pile up?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["On waking","When leaving","Midday","On returning","Before bed","My schedule changes"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose one moment, not the whole day, to observe this week.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5e71f8fc-d8e0-247a-7960-3ff21fffcbe6', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 2, 'See the real load', 'Reconstruct that moment yesterday: what were you trying to do at once?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"Reconstruct that moment yesterday: what were you trying to do at once?","body":"Up to three tasks, without judging how they went.","elara":"That helps. You can change it any time.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Task 1","Task 2","Task 3"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Put the tasks in the order they appeared.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f235c33c-afdf-f40b-a949-313171e16b40', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 3, 'See the real load', 'What work do you do then that rarely gets counted as work?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What work do you do then that rarely gets counted as work?","body":"It may be remembering, coordinating, caring, or anticipating. If not applicable, name another load.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Add that invisible load to your description of the moment.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '331a0fe2-1913-6f32-b4ad-3afe7d56a331', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 4, 'See the real load', 'Which part depends on you, and which depends on other people''s schedules or needs?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Which part depends on you, and which depends on other people''s schedules or needs?","body":"Two areas with words or marks. Two lists also work.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Mark one part you can adjust and another requiring support or coordination.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e4925391-96a8-cd1a-904e-3a8a504f713e', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 5, 'See the real load', 'What small change would remove one step from that moment?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What small change would remove one step from that moment?","body":"Do not add a whole routine: choose something that simplifies.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write exactly which step would no longer be necessary.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '37516262-0cdf-27fa-d20c-88bc7762119c', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 6, 'See the real load', 'What do you have available to try that change?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What do you have available to try that change?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["A few minutes","An item at hand","Someone''s help","I can change the order","Nothing for now","Not sure"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Adapt the change to an available resource, or record the barrier.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4dfd0adb-2653-58a7-3cea-c46ecf2f8f59', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 7, 'See the real load', 'Which part of your day needs fewer demands, rather than more discipline?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Remove friction","letter":"This week was about “See the real load”. What you wrote to keep: “{d7.ask}”. It is yours to reuse, change or leave. Next week: Remove friction.","letterFallback":"This week was about “See the real load”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Remove friction."}', NULL, '[{"id":"ask","kind":"reflect","title":"Which part of your day needs fewer demands, rather than more discipline?","body":"Name the moment and one expectation you could lower.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Leave a more realistic expectation for that time of day.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '00d5430e-f3b9-9f47-e8c2-8afb0f0019f4', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 8, 'Remove friction', 'What small task becomes difficult because too many steps come before it?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a task with fewer steps and a minimum version.","weekTitle":"Remove friction","intro":{"title":"Remove friction","note":"Week 2: Remove friction. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What small task becomes difficult because too many steps come before it?","body":"Choose something everyday and concrete.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"List only the steps before the task begins.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3ea7c9f7-ec02-1892-19c1-2dffc4382129', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 9, 'Remove friction', 'What is the first obstacle you encounter when starting?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What is the first obstacle you encounter when starting?","body":"Choose one.","elara":"Noted. Nothing here has to be perfect.","config":{"optional":true,"options":["Cannot find something","Do not know where to start","Interruptions","Too much setup","No time","Other"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Choose one obstacle to reduce without redesigning your whole life.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'beafddd8-ee93-ed9e-0057-ce13df3c3acb', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 10, 'Remove friction', 'What could you leave ready without creating another demanding task?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"What could you leave ready without creating another demanding task?","body":"Optional photo of an object or corner without personal information; you can describe it instead.","elara":"Thank you. That is enough to work with.","config":{"quiet":true,"optional":true,"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"If possible, prepare one thing; a photo is not required to complete the day.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4794084f-1a2c-2e45-57f0-b2fe90a69dcf', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 11, 'Remove friction', 'What existing moment could you connect that first step to?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What existing moment could you connect that first step to?","body":"If your schedule changes, use an event: “After arriving…”.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Draft a starting cue based on an actual event.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f6b826cc-6eda-0474-4ba9-dfe9ac5e98b6', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 12, 'Remove friction', 'What version would be useful enough on a difficult day?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What version would be useful enough on a difficult day?","body":"It need not meet the ideal version. Define the minimum that would help.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write the small version beside the usual one.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'eef86d9b-5711-2b86-dd46-4ab3f4c95b21', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 13, 'Remove friction', 'What happened when you tried it or considered trying it?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"What happened when you tried it or considered trying it?","body":"Choose one.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"options":["It was easier","Just as difficult","Added work","I was interrupted","Did not try","No longer useful"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note what happened just before the plan helped or failed.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ad9d7671-0031-cc5f-fd1d-4a84e09c0cb6', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 14, 'Remove friction', 'What step can you remove or move after what you observed?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Share and coordinate","letter":"This week was about “Remove friction”. What you wrote to keep: “{d14.ask}”. It is yours to reuse, change or leave. Next week: Share and coordinate.","letterFallback":"This week was about “Remove friction”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Share and coordinate."}', NULL, '[{"id":"ask","kind":"reflect","title":"What step can you remove or move after what you observed?","body":"If you did not try, identify missing preparation or decide to let it go.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Change one step or drop the experiment if it adds more load.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '78eb27ed-fe79-b069-ec6d-847d987d4b2b', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 15, 'Share and coordinate', 'What request or interruption tends to disrupt your plans?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a concrete request or adjustment in scope.","weekTitle":"Share and coordinate","intro":{"title":"Share and coordinate","note":"Week 3: Share and coordinate. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"reflect","title":"What request or interruption tends to disrupt your plans?","body":"Choose one that repeats; no need to identify anyone.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Note whether the interruption is predictable or needs extra room.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'cf8cb347-00ce-7e5f-8cb7-0bd52324843f', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 16, 'Share and coordinate', 'Which interruptions actually require immediate attention?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"Which interruptions actually require immediate attention?","elara":"Thank you. That is enough to work with.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Needs attention now","Can wait in my situation"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep one useful distinction between urgent and pending in your context.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7f4b27d2-bff8-874a-260a-8c1fe57c96b6', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 17, 'Share and coordinate', 'What help could you request as a whole task instead of directing every step?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What help could you request as a whole task instead of directing every step?","body":"If no help is available, name a task you could reduce or postpone.","elara":"That helps. You can change it any time.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Draft the request with the needed result, not a list of orders.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
