INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '869c210f-6c75-82fa-6afc-046ca922384c', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 21, 'Share and coordinate', 'What conversation or adjustment would reduce coordination most next week?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Days that go off course","letter":"This week was about “Share and coordinate”. What you wrote to keep: “{d21.ask}”. It is yours to reuse, change or leave. Next week: Days that go off course.","letterFallback":"This week was about “Share and coordinate”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. Next week: Days that go off course."}', NULL, '[{"id":"ask","kind":"reflect","title":"What conversation or adjustment would reduce coordination most next week?","body":"Leave a draft; no need to send it.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep a proposed agreement stating who does what, if someone else is available.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5ac50824-de7f-ac29-faa4-4562a5c4da5e', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 22, 'Days that go off course', 'Think of a day that went off course. What needed to keep working, and what could wait?', NULL, 'reflect', '{"minutes":4,"payoff":"This week''s takeaway: a minimum plan and a reentry point.","weekTitle":"Days that go off course","intro":{"title":"Days that go off course","note":"Week 4: Days that go off course. Every question is optional: you can skip one, use an example instead of your own situation, and keep anything private. Nothing here asks you to contact anyone, spend money or share what you write."}}', NULL, '[{"id":"ask","kind":"blanks","title":"Think of a day that went off course. What needed to keep working, and what could wait?","body":"Up to two items per group.","elara":"Thank you. That is enough to work with.","config":{"optional":true,"skipLabel":"Prefer to skip","fields":["Needs to keep working (1)","Needs to keep working (2)","Can wait (1)","Can wait (2)"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep essentials separate from what can wait.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
