INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3ac11459-5938-994b-ec36-fd07b5835643', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 31, 'A rhythm that adapts', 'What moment would you like to leave unoptimized?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What moment would you like to leave unoptimized?","body":"Not every rest or enjoyment needs to become a goal.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Leave that moment without tracking or a performance target.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b78a4e78-d876-ab83-e485-8d7abd564865', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 32, 'A rhythm that adapts', 'What needs reviewing when your schedule changes?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"What needs reviewing when your schedule changes?","body":"Choose any that fit. You can also pick none.","elara":"That helps. You can change it any time.","config":{"optional":true,"maxSelections":6,"options":["Task order","Travel time","Care arrangements","Time for myself","Commitments","Something else"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Make a short list to review when the schedule changes.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ee9b0af2-61f4-66d6-ecad-3e6df1f4d9b8', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 33, 'A rhythm that adapts', 'How would you like to review your week without grading yourself as a person?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"How would you like to review your week without grading yourself as a person?","body":"Choose two practical questions, such as “What was too much? What was missing?”.","elara":"Noted. Nothing here has to be perfect.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Keep your two questions as an optional review without scoring.","elara":"Whatever you wrote, you can come back to it.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '47903cc8-f854-60a8-a033-3508046eea2b', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 34, 'A rhythm that adapts', 'What agreement with yourself would be sustainable during an imperfect week?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"What agreement with yourself would be sustainable during an imperfect week?","body":"Include a small version and permission to revise it.","elara":"Thank you. That is enough to work with.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefer to skip"}},{"id":"take","kind":"reflect","title":"To take with you","body":"Write the difficult-week version beside the usual version.","elara":"That is yours to keep, change or leave.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7159a86e-1dcf-ad69-7805-3f2aae614c4f', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'en'), 35, 'A rhythm that adapts', 'What useful instructions would you leave for yourself during a very busy week?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"This week was about “A rhythm that adapts”. What you wrote to keep: “{d35.ask}”. It is yours to reuse, change or leave. That is the whole path. Any day is there if you want to come back to it.","letterFallback":"This week was about “A rhythm that adapts”. Whatever you answered, skipped or left for later is still yours: nothing here is a score. That is the whole path. Any day is there if you want to come back to it."}', NULL, '[{"id":"ask","kind":"blanks","title":"What useful instructions would you leave for yourself during a very busy week?","body":"Complete only the lines you want.","elara":"That helps. You can change it any time.","config":{"optional":true,"keep":"rule","skipLabel":"Prefer to skip","fields":["Prioritize…","Simplify…","This can wait…"]}},{"id":"take","kind":"reflect","title":"To take with you","body":"Check that the three lines reduce decisions instead of adding tasks.","elara":"Small and clear is plenty. It stays with you.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefer to skip"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('d206cb29-0e7d-482a-3d9e-9bfc4b0c43c7', 'money', 'es', 'DINERO', 'Claridad financiera', 'Claridad financiera', 'solar:wallet-money-bold-duotone', '#D97706', 'Desenreda la presión y el peso mental que traes con el dinero.', 0, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '163bacaa-4758-dfa5-2e24-ffbefe64110b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 1, 'Mirar sin juzgar', '¿Qué te gustaría entender mejor sobre tu dinero ahora?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: una descripción de la situación y datos pendientes.","weekTitle":"Mirar sin juzgar","intro":{"title":"Mirar sin juzgar","note":"Semana 1: Mirar sin juzgar. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué te gustaría entender mejor sobre tu dinero ahora?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Lo que gano","Cuándo llega","Lo que necesito pagar","Mis deudas","Mi independencia","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe una pregunta concreta sobre el tema elegido.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '8c254a99-40b0-ae48-36de-92f0480a4d49', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 2, 'Mirar sin juzgar', '¿Cómo entra el dinero en tu vida actualmente?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Cómo entra el dinero en tu vida actualmente?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"exclusiveOption":5,"optional":true,"maxSelections":6,"options":["Trabajo","Clientes o ventas","Apoyo de otras personas","Ayudas o prestaciones","Otra fuente","Ahora no entra"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca qué ingreso es confirmado y cuál es incierto; no sumes promesas como si ya hubieran llegado.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b13fd69f-8dc7-1c60-4455-c96852d5e820', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 3, 'Mirar sin juzgar', '¿Qué pagos necesitas tener presentes antes de que vuelva a entrar dinero?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué pagos necesitas tener presentes antes de que vuelva a entrar dinero?","body":"Anota hasta tres conceptos; las cantidades son opcionales.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Concepto 1","Concepto 2","Concepto 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade una fecha conocida o «por confirmar» junto a cada pago.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '04cfc01f-c974-68ee-e362-e702e79d4d46', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 4, 'Mirar sin juzgar', '¿Qué describe mejor lo que pasa entre tus ingresos y lo necesario?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué describe mejor lo que pasa entre tus ingresos y lo necesario?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Alcanza y queda algo","Alcanza justo","No alcanza","Cambia cada vez","No tengo ingresos ahora","Aún no lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota si necesitas entender un déficit, una variación o una falta de información.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '12d8df9e-1886-8394-0c0d-62b66ccdbdc8', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 5, 'Mirar sin juzgar', '¿Qué información te falta para entender un pago o un ingreso?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué información te falta para entender un pago o un ingreso?","body":"Puede ser fecha, importe, frecuencia o quién lo confirma. No subas documentos.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja preparada una pregunta para la persona o fuente que pueda confirmarlo.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c6f7a362-c1ec-a223-6fe3-6e018de1bbc4', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 6, 'Mirar sin juzgar', '¿Cómo dibujarías el recorrido del dinero que entra y sale?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo dibujarías el recorrido del dinero que entra y sale?","body":"Usa flechas y categorías, sin datos de cuentas. También puedes escribir una lista.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Rodea un punto donde falte información; ese será un posible siguiente paso.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5367a762-49cb-8127-4a9d-d64f987621d5', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 7, 'Mirar sin juzgar', '¿Qué sabes ahora sobre tu dinero que quieres tener a mano?', NULL, 'reflect', '{"minutes":4,"nextWeekTitle":"Ingresos y posibilidades","letter":"Esta semana fue sobre «Mirar sin juzgar». Lo que escribiste para conservar: «{d7.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Ingresos y posibilidades.","letterFallback":"Esta semana fue sobre «Mirar sin juzgar». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Ingresos y posibilidades."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué sabes ahora sobre tu dinero que quieres tener a mano?","body":"Una frase sobre tu situación, sin juzgarte ni prometer cambios.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva tu frase junto a un dato pendiente, sin convertirlo en una promesa.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1dbb8ea9-b3dc-e494-1a65-c022a3f564ab', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 8, 'Ingresos y posibilidades', '¿Qué parte de tus ingresos te gustaría explorar primero?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: un criterio de oportunidad y una pregunta verificable.","weekTitle":"Ingresos y posibilidades","purpose":"Hoy eliges por dónde empezar a mirar tus ingresos y lo conviertes en algo concreto para averiguar.","intro":{"title":"Ingresos y posibilidades","note":"Cada pregunta es opcional, y nada aquí te pide contactar a nadie, gastar dinero ni compartir."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué parte de tus ingresos te gustaría explorar primero?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"noneOption":5,"options":["Encontrar trabajo","Mejorar mi trabajo actual","Cobrar un pago pendiente","Explorar un servicio o venta","Conocer apoyos disponibles","Ninguna por ahora"],"skipLabel":"Prefiero pasar","card":{"label":"Tu elección"}}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"¿Qué podrías averiguar sobre esta opción? Escribe una pregunta o un pequeño paso.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"bodyFallback":"¿Hay algo sobre tus ingresos que te gustaría entender mejor? Si quieres, escríbelo como una pregunta o un pequeño paso.","skipLabel":"Prefiero pasar","card":{"label":"Para llevarte","hint":"Una pregunta o un pequeño paso"}}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5d59a2a1-ab03-86e6-f201-7adb42845a75', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 9, 'Ingresos y posibilidades', '¿Qué sabes hacer que podría servir en una oportunidad que te interesa?', NULL, 'reflect', '{"minutes":4,"purpose":"Hoy buscas en lo que ya sabes hacer un ejemplo concreto y lo conviertes en una frase que podrías usar."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué sabes hacer que podría servir en una oportunidad que te interesa?","body":"Menciona un ejemplo concreto, también de experiencia informal.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar","card":{"label":"Lo que sabes hacer"}}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Convierte tu ejemplo en una línea que podrías usar para describir tu experiencia.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"bodyFallback":"Piensa en algo que sabes hacer, también en casa o en un trabajo informal, y escríbelo en una frase sobre tu experiencia.","skipLabel":"Prefiero pasar","card":{"label":"Para llevarte","hint":"Una frase sobre tu experiencia"}}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '48cbd18e-9e78-dc54-dba0-ddadd861dfe3', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 10, 'Ingresos y posibilidades', '¿Qué condiciones tendría que respetar una oportunidad para que fuera viable?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué condiciones tendría que respetar una oportunidad para que fuera viable?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"maxSelections":6,"options":["Horario","Cuidados","Transporte","Acceso a internet","No pagar por adelantado","Otra condición"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Señala una condición imprescindible antes de dedicar tiempo a una oferta.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '10530f4e-20ae-9b9f-b5de-81486698d318', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 11, 'Ingresos y posibilidades', '¿Qué dato real podrías comprobar sobre una oportunidad antes de dedicarle tiempo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué dato real podrías comprobar sobre una oportunidad antes de dedicarle tiempo?","body":"Por ejemplo: tareas, horario, requisitos o remuneración publicada. Comprobarlo es opcional.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota dónde comprobarías el dato y qué sigue sin verificarse.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3209d99d-5398-26a8-4ea5-9ba343ef8a23', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 12, 'Ingresos y posibilidades', '¿Qué frase podrías usar para pedir información sobre trabajo, precio o un pago pendiente?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué frase podrías usar para pedir información sobre trabajo, precio o un pago pendiente?","body":"Borrador privado: «Quisiera confirmar ___». No hace falta enviarlo.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda el borrador; revisa que pida un dato concreto y no incluya información sensible.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3fe1b334-acee-4f2b-407f-e0afa67cf26f', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 13, 'Ingresos y posibilidades', '¿Qué señal te haría detenerte y comprobar mejor una oferta?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué señal te haría detenerte y comprobar mejor una oferta?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Me piden pagar primero","Prometen ganancias seguras","No explican las tareas","Piden datos sensibles muy pronto","Me presionan para decidir","Otra señal"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe «Pauso y verifico» junto a la señal elegida. Una señal no demuestra por sí sola un fraude.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'adbfa870-47f9-a39d-c1fd-4c9415768b2b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 14, 'Ingresos y posibilidades', '¿Qué opción de ingresos merece una pequeña comprobación más, si alguna?', NULL, 'reflect', '{"minutes":4,"nextWeekTitle":"Decidir con información","letter":"Esta semana fue sobre «Ingresos y posibilidades». Lo que escribiste para conservar: «{d14.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Decidir con información.","letterFallback":"Esta semana fue sobre «Ingresos y posibilidades». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Decidir con información."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué opción de ingresos merece una pequeña comprobación más, si alguna?","body":"Elige una opción y un dato pendiente. «Ninguna por ahora» también vale.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Define una comprobación que puedas hacer sin pagar ni compartir datos sensibles.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '8ea36aca-dae9-2bc2-50b4-d17233bf79bc', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 15, 'Decidir con información', '¿Qué gasto reciente te gustaría comprender mejor, sin decidir todavía si cambiarlo?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una pregunta sobre obligaciones y un criterio de decisión.","weekTitle":"Decidir con información","intro":{"title":"Decidir con información","note":"Semana 3: Decidir con información. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué gasto reciente te gustaría comprender mejor, sin decidir todavía si cambiarlo?","body":"Puedes describir para qué sirvió sin indicar el importe.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon nombre a la necesidad que cubrió el gasto antes de juzgarlo.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '642f1c73-5c11-607e-3e5b-a7d67a02691a', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 16, 'Decidir con información', '¿Qué función cumplió ese gasto, o uno que recuerdes?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué función cumplió ese gasto, o uno que recuerdes?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Algo básico","Trabajo o cuidados","Disfrute","Un imprevisto","Un compromiso con alguien","Otra función"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota si esa necesidad seguirá presente la próxima vez.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5b235392-7a0f-f12b-9b5b-845ab637ce5d', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 17, 'Decidir con información', '¿Qué pago repetido te gustaría revisar para entender qué incluye?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué pago repetido te gustaría revisar para entender qué incluye?","body":"Anota el concepto y lo que no está claro. No implica cancelarlo.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Busca o deja anotado dónde ver el concepto y las condiciones; no canceles por impulso.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5b832b29-50b2-b8ba-7093-b5a7d8232d38', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 18, 'Decidir con información', '¿Qué dato necesitas aclarar sobre una deuda u obligación, si tienes alguna?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué dato necesitas aclarar sobre una deuda u obligación, si tienes alguna?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Saldo","Fecha","Cuota","Intereses o cargos","Condiciones","No aplica"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Prepara una pregunta sobre el dato elegido; si no aplica, marca «sin deuda que revisar».","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6f388a61-17dc-1cf7-5976-de2a092cbe03', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 19, 'Decidir con información', '¿Qué pesa más cuando decides ayudar económicamente a alguien?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué pesa más cuando decides ayudar económicamente a alguien?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Lo básico que debo cubrir","Un acuerdo previo","El deseo de ayudar","La presión que siento","No poder decidir libremente","No aplica u otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe qué necesitarías saber antes de comprometer dinero; no hace falta confrontar a nadie.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '707303a7-f1b7-bffa-f48c-5cf0acc899bc', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 20, 'Decidir con información', '¿Qué frase te ayudaría a ganar tiempo antes de aceptar un compromiso de dinero?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué frase te ayudaría a ganar tiempo antes de aceptar un compromiso de dinero?","body":"Por ejemplo: «Necesito revisar lo que puedo asumir». Solo si es seguro decirlo.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja la frase disponible como borrador privado.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'acbbcfd5-9608-f112-0756-e688a9c94011', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 21, 'Decidir con información', '¿Qué criterio quieres recordar la próxima vez que tomes una decisión de dinero?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Un intento concreto","letter":"Esta semana fue sobre «Decidir con información». Lo que escribiste para conservar: «{d21.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Un intento concreto.","letterFallback":"Esta semana fue sobre «Decidir con información». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Un intento concreto."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué criterio quieres recordar la próxima vez que tomes una decisión de dinero?","body":"Algo específico: comprobar una fecha, preguntar el coste total o revisar lo básico.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Reduce tu criterio a una comprobación breve que puedas recordar.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'cfeac923-5343-b056-2acc-8af7459f6952', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 22, 'Un intento concreto', '¿Qué tarea pequeña te ayudaría a tener más claridad esta semana?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: una tarea acotada, su resultado o la barrera real.","weekTitle":"Un intento concreto","intro":{"title":"Un intento concreto","note":"Semana 4: Un intento concreto. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué tarea pequeña te ayudaría a tener más claridad esta semana?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Confirmar un ingreso","Aclarar un pago","Revisar una oportunidad","Ordenar mis notas","Pedir información","Dejarlo por ahora"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe qué resultado observable tendría la tarea: un dato, una respuesta o una nota.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f1b3833c-31f6-dab2-2318-9fc647459d5f', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 23, 'Un intento concreto', '¿Qué versión de esa tarea cabe en el tiempo y los recursos que tienes?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué versión de esa tarea cabe en el tiempo y los recursos que tienes?","body":"Si no elegiste tarea, puedes nombrar qué necesitarías antes de elegir una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Define el primer paso; si faltan recursos, deja nombrada esa condición.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4a92e077-238a-0fb2-1ebb-cc0560268f91', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 24, 'Un intento concreto', '¿Qué recordatorio te ayudaría a retomar tu tarea sin tener que empezar a pensarla de nuevo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"¿Qué recordatorio te ayudaría a retomar tu tarea sin tener que empezar a pensarla de nuevo?","body":"Opcional: foto de una nota sin nombres, importes ni datos. Nunca cuentas, tarjetas o documentos.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"quiet":true,"optional":true,"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Crea un recordatorio sin datos financieros, en foto o texto.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '366ddaef-944a-8dc7-1501-0b449f541281', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 25, 'Un intento concreto', '¿Qué describe mejor cómo va tu tarea?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué describe mejor cómo va tu tarea?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["La hice","Hice una parte","Aún no","Necesito cambiarla","La dejé por ahora","No elegí una"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota el siguiente dato que falta, o marca que por ahora no continuarás.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '14fd655e-a012-b825-75fd-efcbf298c2c9', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 26, 'Un intento concreto', '¿Qué aprendiste al intentar la tarea, o qué impidió que fuera posible?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué aprendiste al intentar la tarea, o qué impidió que fuera posible?","body":"Cuenta un hecho, sin evaluar tu disciplina.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Separa el resultado del obstáculo: no recibir respuesta no significa haber hecho mal la tarea.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7f5e1650-8394-eae7-eaf7-d9816115a61b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 27, 'Un intento concreto', '¿Qué conviene ajustar en el siguiente intento, si quieres hacer uno?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué conviene ajustar en el siguiente intento, si quieres hacer uno?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Hacerlo más pequeño","Buscar otra fuente","Elegir otro momento","Pedir apoyo","Cambiar de tarea","No seguir por ahora"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige solo un ajuste; si paras, registra qué queda pendiente.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5dd7cc28-1e74-9593-9510-f103079db27f', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 28, 'Un intento concreto', '¿Qué información o herramienta de esta semana te resulta útil conservar?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Una claridad que continúa","letter":"Esta semana fue sobre «Un intento concreto». Lo que escribiste para conservar: «{d28.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Una claridad que continúa.","letterFallback":"Esta semana fue sobre «Un intento concreto». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Una claridad que continúa."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué información o herramienta de esta semana te resulta útil conservar?","body":"Puede ser una fecha confirmada, una pregunta o una frase. No hace falta haber terminado la tarea.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon un título claro a lo que conservarás para encontrarlo después.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b476ee53-8b99-398e-920e-dc97cdaf4603', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 29, 'Una claridad que continúa', '¿Qué ha cambiado en tu comprensión del dinero, aunque los ingresos sigan igual?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una nota de situación y una revisión opcional.","weekTitle":"Una claridad que continúa","intro":{"title":"Una claridad que continúa","note":"Semana 5: Una claridad que continúa. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué ha cambiado en tu comprensión del dinero, aunque los ingresos sigan igual?","body":"También puedes escribir «Nada todavía».","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Compara una duda inicial con lo que sabes ahora; «sigue abierta» cuenta.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd7594321-6e7c-a507-e24e-a620500aa4a6', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 30, 'Una claridad que continúa', '¿Qué te ayudaría a orientarte en una semana con menos ingresos de lo esperado?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué te ayudaría a orientarte en una semana con menos ingresos de lo esperado?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"maxSelections":6,"options":["Ver fechas y pagos","Confirmar lo que entrará","Conocer apoyos","Pedir aclaraciones","Revisar un acuerdo","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una lista de dos datos que revisarías primero, sin imponer recortes.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a6501fb3-7a58-29d2-beae-9c47f8e51ecf', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 31, 'Una claridad que continúa', '¿Qué te gustaría poder decidir con más información o autonomía?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué te gustaría poder decidir con más información o autonomía?","body":"No hace falta cambiar acuerdos ni hablar con nadie hoy.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota una información que aumentaría tu margen para esa decisión.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '07b50242-3c1e-07c7-8be5-e996cd574352', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 32, 'Una claridad que continúa', '¿Qué apoyo o información podría ayudarte con algo que sigue pendiente?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué apoyo o información podría ayudarte con algo que sigue pendiente?","body":"Nombra el tipo de ayuda; no necesitas datos de contacto ni buscarla ahora.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe una pregunta que llevarías a una fuente de apoyo adecuada a tu situación.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'da6eccfa-541f-9bbd-d726-5eeb77e9223b', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 33, 'Una claridad que continúa', '¿Qué revisión breve de tu dinero sería útil repetir?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué revisión breve de tu dinero sería útil repetir?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Fechas de ingreso","Próximos pagos","Una deuda u obligación","Oportunidades o cobros","Mis acuerdos","Ninguna por ahora"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Define qué mirarías en esa revisión y cuándo darla por terminada.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd864d796-2492-db6a-36c9-1fb6c0a33ba6', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 34, 'Una claridad que continúa', '¿Cuándo te serviría volver a mirar tu situación?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cuándo te serviría volver a mirar tu situación?","body":"Puedes nombrar un momento o evento. Esto no crea un recordatorio.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si te sirve, anota ese momento en tu propio calendario; la app no lo programará aquí.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2877f553-8f80-9485-4bbd-ab9863faedc1', (SELECT id FROM path_content WHERE area = 'money' AND locale = 'es'), 35, 'Una claridad que continúa', '¿Qué quieres incluir en tu nota de claridad financiera?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"Esta semana fue sobre «Una claridad que continúa». Lo que escribiste para conservar: «{d35.ask}». Es tuyo para reutilizar, cambiar o dejar. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él.","letterFallback":"Esta semana fue sobre «Una claridad que continúa». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué quieres incluir en tu nota de claridad financiera?","body":"Completa solo las líneas que quieras.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Ahora sé…","Sigue pendiente…","Mi próximo paso, si lo hay…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Revisa que tu nota distinga hechos, dudas y un paso opcional.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('52cec2d4-5be6-c6c1-03e3-5ebc79f156df', 'self', 'es', 'TÚ', 'Confianza en ti', 'Confianza en ti', 'solar:sun-fog-bold-duotone', '#945C4F', 'Separa tu voz verdadera del ruido del juicio.', 1, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '094eb52a-b946-fb6c-defd-a6ffc2b86969', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 1, 'Escuchar tu criterio', '¿Qué decisión pequeña te ha hecho buscar aprobación últimamente?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una preferencia y evidencia concreta de capacidad.","weekTitle":"Escuchar tu criterio","intro":{"title":"Escuchar tu criterio","note":"Semana 1: Escuchar tu criterio. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué decisión pequeña te ha hecho buscar aprobación últimamente?","body":"Elige algo cotidiano; no necesitas exponer una decisión íntima.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra qué esperabas recibir al pedir aprobación: un dato, compañía o permiso.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5f6e3b7e-9f51-1067-dfde-f224aba17a68', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 2, 'Escuchar tu criterio', '¿Qué te dices cuando no tienes certeza sobre una elección?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué te dices cuando no tienes certeza sobre una elección?","body":"Una frase tal como aparece, sin tener que creerla.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe la frase como un pensamiento que aparece, no como un hecho demostrado.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'cb5023c1-52d1-8bfb-c89c-5192e6aeaf5e', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 3, 'Escuchar tu criterio', '¿Qué parte de esa preocupación sabes y qué parte estás imaginando?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué parte de esa preocupación sabes y qué parte estás imaginando?","body":"También puedes usar una situación nueva.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Hechos","Lo que imagino"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca un dato que puedas comprobar y una incertidumbre que deba seguir abierta.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b6ac35ba-9d79-98b4-0a86-ea724f61280d', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 4, 'Escuchar tu criterio', '¿Qué has decidido antes que salió suficientemente bien, aunque no fuera perfecto?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué has decidido antes que salió suficientemente bien, aunque no fuera perfecto?","body":"Una elección pequeña cuenta. Si no recuerdas una, describe una tarea que resolviste.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota qué información tenías cuando elegiste, sin usar lo que supiste después.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '822df890-28b2-9c6e-8ba1-4690d97faa02', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 5, 'Escuchar tu criterio', '¿Qué hiciste tú que ayudó en esa situación?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué hiciste tú que ayudó en esa situación?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"maxSelections":6,"options":["Pregunté","Me preparé","Me adapté","Pedí ayuda","Elegí con lo que sabía","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva una conducta concreta que puedas repetir.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c78452e5-6754-68af-f85e-5f97a3949569', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 6, 'Escuchar tu criterio', '¿Qué preferencia pequeña podrías expresar sin justificarla demasiado?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué preferencia pequeña podrías expresar sin justificarla demasiado?","body":"Ensaya «Prefiero ___». Puedes dejarlo solo aquí.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja lista una frase de preferencia; decirla en voz alta es opcional.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '46d9746d-7e40-09c8-a685-55c5103be3f3', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 7, 'Escuchar tu criterio', '¿Qué evidencia sobre ti quieres recordar cuando vuelvas a dudar?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Tu voz entre otras","letter":"Esta semana fue sobre «Escuchar tu criterio». Lo que escribiste para conservar: «{d7.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Tu voz entre otras.","letterFallback":"Esta semana fue sobre «Escuchar tu criterio». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Tu voz entre otras."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué evidencia sobre ti quieres recordar cuando vuelvas a dudar?","body":"Guarda un hecho, no una afirmación que no te crees.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Titula tu nota con el hecho concreto que recuerdas.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b2590c71-f6d7-1e17-46d7-4a370139e995', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 8, 'Tu voz entre otras', '¿De quién suele ser la opinión que pesa más al decidir?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: un criterio propio con contexto, sin comparación injusta.","weekTitle":"Tu voz entre otras","intro":{"title":"Tu voz entre otras","note":"Semana 2: Tu voz entre otras. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿De quién suele ser la opinión que pesa más al decidir?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Alguien cercano","Una autoridad","Personas en redes","Mi propia expectativa","Depende","Otra fuente"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Identifica si esa opinión aporta experiencia relevante para esta decisión.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'bb0c1e32-2adc-e51b-5001-b35447e00d15', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 9, 'Tu voz entre otras', '¿Qué tiene de útil esa opinión y qué no encaja con tu situación?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué tiene de útil esa opinión y qué no encaja con tu situación?","body":"No hace falta rechazar toda la opinión para decidir distinto.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Lo que me sirve","Lo que no encaja"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Subraya la parte útil y deja fuera una parte que no encaja.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a8b34f6b-613f-3233-72c0-4c3dfe8a7477', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 10, 'Tu voz entre otras', '¿Qué comparación reciente te hizo sentir que ibas tarde?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué comparación reciente te hizo sentir que ibas tarde?","body":"Si no aplica, elige una expectativa de tiempo que quieras revisar.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota qué plazo estás tomando como regla y de dónde viene.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '87c76138-7aed-2605-7959-08bcd31bbc07', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 11, 'Tu voz entre otras', '¿Qué parte de tu contexto desaparece cuando haces esa comparación?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué parte de tu contexto desaparece cuando haces esa comparación?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"maxSelections":6,"options":["Recursos","Cuidados","Salud o energía","Oportunidades","Prioridades distintas","Otra parte"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade una condición omitida a la comparación.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5aa9c7bd-6ba4-7d4c-1466-fc74d0588f58', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 12, 'Tu voz entre otras', '¿Cómo distinguirías lo que quieres de lo que intentas demostrar?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo distinguirías lo que quieres de lo que intentas demostrar?","body":"Dos espacios, con palabras o símbolos. Pueden solaparse.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige una preferencia que tendría valor aunque nadie la viera.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f34d34d2-6aa9-c5b6-12b3-485e96288c76', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 13, 'Tu voz entre otras', '¿Qué consejo aceptarías como información, sin convertirlo en una orden?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué consejo aceptarías como información, sin convertirlo en una orden?","body":"Completa «Voy a considerar ___; la decisión sobre ___ sigue siendo mía».","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Prepara tu frase para releerla antes de pedir otra opinión.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'cc806fe0-1d51-48ec-6269-85dbaa0d4fd0', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 14, 'Tu voz entre otras', '¿Qué criterio propio quieres usar en una decisión próxima?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Cumplirte en pequeño","letter":"Esta semana fue sobre «Tu voz entre otras». Lo que escribiste para conservar: «{d14.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Cumplirte en pequeño.","letterFallback":"Esta semana fue sobre «Tu voz entre otras». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Cumplirte en pequeño."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué criterio propio quieres usar en una decisión próxima?","body":"Una condición concreta como tiempo, interés, coste o tranquilidad.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe cómo reconocerías que se cumple tu criterio.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4b83780c-cfd8-2729-5d40-5bb44a33de6b', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 15, 'Cumplirte en pequeño', '¿Qué compromiso contigo sería pequeño de verdad esta semana?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: un compromiso realista y un ajuste sin castigo.","weekTitle":"Cumplirte en pequeño","intro":{"title":"Cumplirte en pequeño","note":"Semana 3: Cumplirte en pequeño. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué compromiso contigo sería pequeño de verdad esta semana?","body":"Algo que dependa principalmente de ti; también puedes no elegir uno.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Define un resultado pequeño y bajo tu control, o elige no comprometerte.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6415b01f-f2ae-b709-6892-5bdd170a7af1', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 16, 'Cumplirte en pequeño', '¿Qué suele hacer difícil cumplir un compromiso como ese?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué suele hacer difícil cumplir un compromiso como ese?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Es demasiado grande","No tiene un momento","Dependo de alguien","Aparecen imprevistos","No me importa tanto","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Cambia una condición del compromiso según el obstáculo elegido.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '8405a1b6-d527-98f8-361c-27ff4100a8e1', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 17, 'Cumplirte en pequeño', '¿Cuál sería la versión mínima que todavía tendría sentido para ti?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cuál sería la versión mínima que todavía tendría sentido para ti?","body":"Reducirlo no significa hacerlo inútil. Puede ser un solo paso.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe la versión mínima con un principio y un final claros.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9405879c-ad64-a903-d8fa-60599d3f7018', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 18, 'Cumplirte en pequeño', '¿Qué señal visible te recordaría tu compromiso sin presionarte?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"¿Qué señal visible te recordaría tu compromiso sin presionarte?","body":"Foto opcional de un objeto o nota sin datos personales.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"quiet":true,"optional":true,"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon la señal donde te sirva, si hacerlo es posible y privado.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd3c7e4aa-0208-cfb8-70a1-5ff63db5a74c', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 19, 'Cumplirte en pequeño', '¿Qué ocurrió con el compromiso que elegiste?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué ocurrió con el compromiso que elegiste?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Lo hice","Hice una parte","Lo cambié","No fue posible","Decidí no hacerlo","No elegí uno"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Registra lo ocurrido sin convertirlo en una etiqueta sobre ti.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'fcf7a7ab-6b46-de45-8285-a04e6d6d20b3', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 20, 'Cumplirte en pequeño', '¿Qué ajuste sería más justo que llamarte incapaz o floja?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué ajuste sería más justo que llamarte incapaz o floja?","body":"Si esos juicios no aparecen, nombra simplemente un ajuste útil.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Reescribe el compromiso con el ajuste, o retíralo si ya no sirve.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b9507dff-4c9e-7398-144c-81c3fdd33ff1', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 21, 'Cumplirte en pequeño', 'Si el compromiso no salió como esperabas, ¿qué ajuste sería más justo que culparte?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Elegir sin certeza total","letter":"Esta semana fue sobre «Cumplirte en pequeño». Lo que escribiste para conservar: «{d21.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Elegir sin certeza total.","letterFallback":"Esta semana fue sobre «Cumplirte en pequeño». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Elegir sin certeza total."}', NULL, '[{"id":"ask","kind":"reflect","title":"Si el compromiso no salió como esperabas, ¿qué ajuste sería más justo que culparte?","body":"Incluye las condiciones que ayudaron o faltaron.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva una condición que te ayudó o que necesitarías la próxima vez.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '51eb51aa-45ad-f7c5-29b6-016f9916810c', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 22, 'Elegir sin certeza total', '¿Qué decisión estás posponiendo porque esperas sentirte totalmente segura?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una decisión cotidiana revisable.","weekTitle":"Elegir sin certeza total","intro":{"title":"Elegir sin certeza total","note":"Semana 4: Elegir sin certeza total. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué decisión estás posponiendo porque esperas sentirte totalmente segura?","body":"Elige una decisión pequeña y reversible, no una de alto riesgo.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Limita el ejercicio a una decisión cotidiana que puedas revisar.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f7080662-cd99-cf1c-c22a-7e15ffc1860a', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 23, 'Elegir sin certeza total', '¿Qué información sería suficiente para decidir ese pequeño asunto?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué información sería suficiente para decidir ese pequeño asunto?","body":"Hasta tres datos. Distingue lo necesario de lo que sería agradable saber.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Dato 1","Dato 2","Dato 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca cuál de esos datos falta realmente.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'fe27be45-4a29-6700-602f-8fe086a377b4', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 24, 'Elegir sin certeza total', '¿Qué parte de esa decisión podrías cambiar después?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte de esa decisión podrías cambiar después?","body":"Si no es reversible, elige otra decisión pequeña para este ejercicio.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota cómo podrías revisar la elección, sin prometer que no habrá molestias.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7ec31bbe-a0f9-d0d1-cb32-bb76d409a7b4', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 25, 'Elegir sin certeza total', '¿Qué te haría elegir entre dos opciones suficientemente buenas?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué te haría elegir entre dos opciones suficientemente buenas?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Mi preferencia","El esfuerzo","El tiempo","El coste","Poder cambiar después","Otro criterio"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige un criterio principal en vez de exigir que una opción gane en todo.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '18d0a27a-54c1-5290-1368-69fe47f2cb67', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 26, 'Elegir sin certeza total', '¿Qué elegirías ahora con la información que sí tienes?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué elegirías ahora con la información que sí tienes?","body":"Puedes elegir esperar y nombrar el dato que falta; no hace falta actuar hoy.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una decisión provisional o una pregunta pendiente claramente escrita.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2732de99-10e6-f11f-c8b1-545aa68ecc55', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 27, 'Elegir sin certeza total', '¿Qué pasó después de elegir, o qué sigue impidiendo decidir?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué pasó después de elegir, o qué sigue impidiendo decidir?","body":"Distingue el resultado de la calidad de tu decisión con lo que sabías.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota una cosa que dependía de ti y otra que no.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '8cb6c678-b550-63c9-b694-6564447c69a0', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 28, 'Elegir sin certeza total', '¿Qué quieres recordar sobre decidir sin certeza total?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Volver a confiar","letter":"Esta semana fue sobre «Elegir sin certeza total». Lo que escribiste para conservar: «{d28.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Volver a confiar.","letterFallback":"Esta semana fue sobre «Elegir sin certeza total». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Volver a confiar."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué quieres recordar sobre decidir sin certeza total?","body":"Escribe algo basado en tu experiencia, no una regla para todas las decisiones.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda una observación aplicable a decisiones pequeñas, no a cualquier riesgo.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '49e9b70a-d606-af40-19e3-e15de25abcca', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 29, 'Volver a confiar', 'Piensa en un error pequeño que aún te pese, si hay alguno. ¿Qué conclusión sobre ti sacaste de él?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una reparación posible y una nota basada en hechos.","weekTitle":"Volver a confiar","intro":{"title":"Volver a confiar","note":"Semana 5: Volver a confiar. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"Piensa en un error pequeño que aún te pese, si hay alguno. ¿Qué conclusión sobre ti sacaste de él?","body":"Puedes usar un ejemplo cotidiano o saltar esta pregunta.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Describe el error como un hecho concreto, sin usar «siempre» ni «soy».","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0b8fd3c7-c143-531c-71e6-db74c599fe44', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 30, 'Volver a confiar', '¿Qué responsabilidad sí te corresponde y qué parte no estaba bajo tu control?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué responsabilidad sí te corresponde y qué parte no estaba bajo tu control?","body":"Reconocer contexto no borra lo que sí puedes reparar.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Mi responsabilidad","Fuera de mi control"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige una responsabilidad específica sin asumir la parte ajena.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '69de77c4-ecfe-686c-6231-b0cd3ee1a68d', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 31, 'Volver a confiar', '¿Hay algo concreto que puedas reparar o aprender de ese error, sin convertirlo en una condena sobre ti?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Hay algo concreto que puedas reparar o aprender de ese error, sin convertirlo en una condena sobre ti?","body":"Si no hay nada que reparar, puedes nombrar una lección o dejarlo aquí.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una reparación posible o una lección concreta; no necesitas castigarte para recordarla.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b03719db-872c-597c-039d-5061b3a63e05', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 32, 'Volver a confiar', '¿Qué pedirías a alguien de confianza sin entregarle toda la decisión?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué pedirías a alguien de confianza sin entregarle toda la decisión?","body":"Borrador: «Ayúdame a pensar en ___; quiero elegir yo». Sin obligación de contactar.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Prepara una petición de perspectiva que conserve tu derecho a decidir.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '08e8b5f1-7b98-0756-0ebc-550cd5089df9', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 33, 'Volver a confiar', '¿Qué frase te ayudaría cuando vuelvas a buscar permiso para algo pequeño?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué frase te ayudaría cuando vuelvas a buscar permiso para algo pequeño?","body":"Di una frase creíble para ti.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Ajusta la frase hasta que suene creíble, aunque sea modesta.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5bf71452-8085-d954-2b6b-19e5da54768a', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 34, 'Volver a confiar', '¿Qué elección o ajuste reciente muestra que puedes escucharte?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué elección o ajuste reciente muestra que puedes escucharte?","body":"Puede ser pedir ayuda, cambiar de idea o decir que no sabías.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade ese ejemplo a tu lista de evidencia personal.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '222e9cbc-5caf-1f5d-8956-462c2dc31883', (SELECT id FROM path_content WHERE area = 'self' AND locale = 'es'), 35, 'Volver a confiar', '¿Qué quieres incluir en una nota de confianza basada en hechos?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"Esta semana fue sobre «Volver a confiar». Lo que escribiste para conservar: «{d35.ask}». Es tuyo para reutilizar, cambiar o dejar. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él.","letterFallback":"Esta semana fue sobre «Volver a confiar». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué quieres incluir en una nota de confianza basada en hechos?","body":"Completa solo las líneas que quieras.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["He podido…","Me ayuda…","Cuando dude, puedo…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva dos hechos y un recurso al que puedas volver cuando dudes.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('6d8be89e-cf10-896d-ae3a-e4d645cf4398', 'energy', 'es', 'ENERGÍA', 'Reinicio de energía', 'Reinicio de energía', 'solar:fire-bold-duotone', '#EC7A4E', 'Recupera tus reservas naturales, de forma sostenible.', 2, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b9c6cb36-233e-f7f4-c480-2ae1759101bc', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 1, 'Notar sin diagnosticar', '¿En qué momento reciente sentiste que ya no te quedaba margen?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: observaciones provisionales sobre cargas y necesidades.","weekTitle":"Notar sin diagnosticar","intro":{"title":"Notar sin diagnosticar","note":"Semana 1: Notar sin diagnosticar. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿En qué momento reciente sentiste que ya no te quedaba margen?","body":"Puede ser físico, mental o social; no tienes que explicar una causa.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Describe el momento sin convertirlo en una explicación de quién eres.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9b0de243-87dd-0a61-b3e1-50f199ca5248', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 2, 'Notar sin diagnosticar', '¿Qué tipo de carga notas más hoy?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué tipo de carga notas más hoy?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Física","Mental","Emocional","Social","Varias","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra una demanda relacionada con esa carga, sin diagnosticar su causa.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4053134e-5704-6e0e-3575-4c1cf34267f8', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 3, 'Notar sin diagnosticar', '¿Qué estaba pasando justo antes de notar ese cansancio?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué estaba pasando justo antes de notar ese cansancio?","body":"Hasta tres hechos, sin buscar un diagnóstico.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Hecho 1","Hecho 2","Hecho 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Separa hechos de explicaciones que todavía no sabes si son ciertas.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '01716137-40f9-9b59-dfc7-91a7d2dae133', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 4, 'Notar sin diagnosticar', 'Dibuja cómo se repartió tu energía ayer. ¿Qué cambio notaste, si hubo alguno?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Dibuja cómo se repartió tu energía ayer. ¿Qué cambio notaste, si hubo alguno?","body":"Una línea o palabras; no hace falta puntuarla.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca un cambio para observar otro día; un solo día no demuestra un patrón.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f406d585-7ce9-118f-ee1a-6e072e729c9d', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 5, 'Notar sin diagnosticar', '¿Qué momento te dejó un poco más de espacio, aunque no te hiciera sentir feliz?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué momento te dejó un poco más de espacio, aunque no te hiciera sentir feliz?","body":"Si ninguno lo hizo, escribe qué habría reducido una demanda.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva el detalle o la demanda que habría sido útil reducir.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '63dc604f-bfcd-2014-df68-09f081af1bcb', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 6, 'Notar sin diagnosticar', '¿Qué necesitas primero cuando estás así?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué necesitas primero cuando estás así?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Menos estímulos","Una necesidad básica","Estar acompañada","Estar sola","Ayuda con una carga","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Define una forma pequeña de atender esa necesidad, o la ayuda que te falta.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3bc3ce47-3adb-a6c9-b2bb-0ce99c9fe0c0', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 7, 'Notar sin diagnosticar', '¿Qué observación sobre tu energía vale la pena recordar sin convertirla en una regla?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Descanso que sí cabe","letter":"Esta semana fue sobre «Notar sin diagnosticar». Lo que escribiste para conservar: «{d7.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Descanso que sí cabe.","letterFallback":"Esta semana fue sobre «Notar sin diagnosticar». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Descanso que sí cabe."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué observación sobre tu energía vale la pena recordar sin convertirla en una regla?","body":"Completa: «Esta semana noté…». Una semana no define todo tu cuerpo.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda la observación como provisional, no como una etiqueta fija.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd8a47359-c6f6-1089-49dd-6839e64f84bd', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 8, 'Descanso que sí cabe', '¿Qué haces para descansar que a veces termina sintiéndose como otra obligación?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una pausa probada o la barrera que la impide.","weekTitle":"Descanso que sí cabe","intro":{"title":"Descanso que sí cabe","note":"Semana 2: Descanso que sí cabe. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué haces para descansar que a veces termina sintiéndose como otra obligación?","body":"Si no te pasa, describe una forma de descanso que sí te sirve.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Quita una exigencia de la idea de descanso que estás usando.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3e76337e-ec9e-2e62-f178-a2a7d6a738bb', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 9, 'Descanso que sí cabe', '¿Qué tendría que parar unos minutos para que pudieras descansar de verdad?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué tendría que parar unos minutos para que pudieras descansar de verdad?","body":"Incluye lo que depende de otras personas o de tus condiciones.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Distingue lo que puedes pausar de lo que necesita relevo o apoyo.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7faca4bc-67a5-750b-4a61-a264aaef7065', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 10, 'Descanso que sí cabe', '¿Qué tipo de pausa te gustaría probar hoy, si tienes margen?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué tipo de pausa te gustaría probar hoy, si tienes margen?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Silencio","Cambiar de postura","Mirar afuera","Algo agradable sin meta","Pedir relevo","Hoy no puedo"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si te sirve, prueba una pausa breve sin obligarte a terminarla ni a sentirte mejor.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2626960b-cae2-766b-9d9f-ecacf9f55a4c', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 11, 'Descanso que sí cabe', '¿Qué hace difícil darte esa pausa?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué hace difícil darte esa pausa?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["No hay tiempo","Nadie me releva","Me siento culpable","No hay espacio","No sé qué ayuda","Otra razón"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota una barrera concreta para no atribuirlo todo a falta de voluntad.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4326ad56-9650-3208-8ada-49b89ce2fc71', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 12, 'Descanso que sí cabe', 'Si hiciste una pausa, ¿cómo te dejó en comparación con antes?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"Si hiciste una pausa, ¿cómo te dejó en comparación con antes?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Con más margen","Igual","Con menos margen","Mezclado","No hice la pausa","No puedo distinguirlo"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Registra el efecto sin calificarte ni insistir en algo que te incomoda.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f168d8b7-b23b-7122-41e0-e5488ec3f00b', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 13, 'Descanso que sí cabe', '¿Qué cambiarías para que la próxima pausa requiera menos esfuerzo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué cambiarías para que la próxima pausa requiera menos esfuerzo?","body":"Puede ser duración, lugar, compañía o decidir no repetirla.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Cambia una condición o deja de probar esa pausa si no te sirve.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '858edfab-5ea2-fbc6-a8e2-8e87416c221a', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 14, 'Descanso que sí cabe', '¿Qué forma de descanso merece seguir disponible sin que tengas que ganártela?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Reducir lo que drena","letter":"Esta semana fue sobre «Descanso que sí cabe». Lo que escribiste para conservar: «{d14.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Reducir lo que drena.","letterFallback":"Esta semana fue sobre «Descanso que sí cabe». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Reducir lo que drena."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué forma de descanso merece seguir disponible sin que tengas que ganártela?","body":"Describe una posibilidad real; no una rutina perfecta.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una opción de descanso disponible, sin convertirla en tarea diaria.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a72cbf44-cfdb-b5df-9ab0-e319b3788cf9', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 15, 'Reducir lo que drena', '¿Qué demanda aceptas casi en automático y luego notas en tu energía?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una demanda ajustable y una necesidad de apoyo.","weekTitle":"Reducir lo que drena","intro":{"title":"Reducir lo que drena","note":"Semana 3: Reducir lo que drena. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué demanda aceptas casi en automático y luego notas en tu energía?","body":"Una demanda cotidiana; también puedes no identificar ninguna.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Identifica el momento en que podrías detenerte antes de responder.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd5ec8a73-b81b-2afa-6a7c-03c035e86543', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 16, 'Reducir lo que drena', '¿Qué parte de esa demanda podría bajar de intensidad?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué parte de esa demanda podría bajar de intensidad?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Duración","Frecuencia","Nivel de detalle","Disponibilidad","Podría compartirla","No puedo cambiarla"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe el ajuste posible o reconoce qué parte no puedes cambiar ahora.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5536c1f9-b869-d7e9-1a2c-c940a4224fd6', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 17, 'Reducir lo que drena', '¿Qué frase te daría tiempo para revisar tu capacidad antes de aceptar?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué frase te daría tiempo para revisar tu capacidad antes de aceptar?","body":"Borrador: «Lo reviso y te confirmo…». Elige un plazo realista.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda la frase para usarla solo cuando sea apropiado y seguro.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2a53e7f8-3a0d-e12b-14ff-5a4c7be158b6', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 18, 'Reducir lo que drena', '¿Qué parte de tu entorno añade carga que casi no notas hasta que desaparece?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué parte de tu entorno añade carga que casi no notas hasta que desaparece?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"exclusiveOption":5,"optional":true,"maxSelections":6,"options":["Ruido","Notificaciones","Desorden visual","Falta de privacidad","Interrupciones","Ninguna de estas"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige un estímulo que puedas reducir sin perder algo necesario.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'eacca457-54ab-4542-fe3c-9152cb79a3a9', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 19, 'Reducir lo que drena', '¿Qué ajuste pequeño del entorno podrías probar sin comprar nada?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"¿Qué ajuste pequeño del entorno podrías probar sin comprar nada?","body":"Foto opcional de un detalle sin datos personales, o descríbelo. No se exige un lugar bonito.","elara":"Gracias. Con eso basta para trabajar.","config":{"quiet":true,"optional":true,"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Prueba un cambio reversible si está a tu alcance, o deja el plan en texto.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd9041386-da43-8b97-292b-abad0d68c0e6', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 20, 'Reducir lo que drena', '¿Qué carga necesita apoyo y no otra estrategia individual?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué carga necesita apoyo y no otra estrategia individual?","body":"Nombra la ayuda concreta; no hace falta saber quién puede darla aún.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Convierte la carga en una petición concreta o una necesidad de apoyo pendiente.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a76aef9c-03d7-04a1-0bf4-8cf4bada0aa3', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 21, 'Reducir lo que drena', '¿Qué demanda quieres reducir, compartir o reconocer como inevitable por ahora?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Curiosidad sin rendimiento","letter":"Esta semana fue sobre «Reducir lo que drena». Lo que escribiste para conservar: «{d21.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Curiosidad sin rendimiento.","letterFallback":"Esta semana fue sobre «Reducir lo que drena». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Curiosidad sin rendimiento."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué demanda quieres reducir, compartir o reconocer como inevitable por ahora?","body":"Elige una. Reconocer un límite real también aporta claridad.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja escrita una decisión sobre esa demanda, aunque sea «necesito ayuda antes».","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3dee6177-7dad-2f6e-cda5-a264ac414b65', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 22, 'Curiosidad sin rendimiento', '¿Qué te despierta curiosidad sin pedirte que seas buena en ello?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una posibilidad de disfrute sin exigir un efecto.","weekTitle":"Curiosidad sin rendimiento","intro":{"title":"Curiosidad sin rendimiento","note":"Semana 4: Curiosidad sin rendimiento. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué te despierta curiosidad sin pedirte que seas buena en ello?","body":"Puede ser un sonido, una historia, una textura o algo cotidiano.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda una idea que te interese sin tener que justificar su utilidad.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ff64ddbe-9193-bbfe-5fd5-df3f660df8d1', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 23, 'Curiosidad sin rendimiento', '¿Qué detalle agradable podrías observar hoy sin convertirlo en una tarea?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"¿Qué detalle agradable podrías observar hoy sin convertirlo en una tarea?","body":"Foto opcional o una frase. Puedes omitirlo si hoy no te sirve.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"quiet":true,"optional":true,"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Describe un detalle observado; no necesitas demostrar gratitud ni bienestar.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0a09b98c-1fb3-0598-b372-7fdc86f317af', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 24, 'Curiosidad sin rendimiento', '¿Qué disfrute has dejado fuera porque parecía poco productivo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué disfrute has dejado fuera porque parecía poco productivo?","body":"Si no hay ninguno, escribe algo que ya disfrutes y quieras conservar.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra qué valor tiene ese disfrute para ti, aunque no produzca nada.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'af399bae-166c-61af-5c48-c4fe1dc5af8b', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 25, 'Curiosidad sin rendimiento', '¿Cuál sería una versión accesible de ese disfrute en tu situación actual?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cuál sería una versión accesible de ese disfrute en tu situación actual?","body":"Sin compras, viajes ni tener que sentirte mejor después.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una versión posible que no requiera gastar ni viajar.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9fb5bd7f-523a-79d7-47bf-a8a919526a46', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 26, 'Curiosidad sin rendimiento', '¿Qué te pasó al acercarte a algo que te interesa, si lo hiciste?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué te pasó al acercarte a algo que te interesa, si lo hiciste?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Me dio curiosidad","Me dio calma","No cambió nada","Me cansó","Sentí varias cosas","No lo hice"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota el efecto tal como fue; «no cambió nada» también informa.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '61158eaf-46ec-0d53-7d8f-ae9616893b52', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 27, 'Curiosidad sin rendimiento', '¿Qué diferencia hay para ti entre distraerte un rato y sentirte renovada?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué diferencia hay para ti entre distraerte un rato y sentirte renovada?","body":"No tienes que elegir una como buena y otra como mala. Usa un ejemplo.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva una diferencia útil para elegir según lo que necesites.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a6c4219c-0794-5586-b4de-9532b0b6fe96', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 28, 'Curiosidad sin rendimiento', '¿Qué posibilidad de disfrute te gustaría tener a mano para otro día?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Cuidar el margen","letter":"Esta semana fue sobre «Curiosidad sin rendimiento». Lo que escribiste para conservar: «{d28.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Cuidar el margen.","letterFallback":"Esta semana fue sobre «Curiosidad sin rendimiento». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Cuidar el margen."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué posibilidad de disfrute te gustaría tener a mano para otro día?","body":"Guarda una idea breve, sin comprometerte a hacerla.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade la idea a una lista opcional, sin asignarle una fecha límite.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '22841c92-b2a5-6c2d-9202-6637b4d7fa2e', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 29, 'Cuidar el margen', '¿Qué señales te gustaría atender antes de llegar a tu límite?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una nota práctica para días de poca energía.","weekTitle":"Cuidar el margen","intro":{"title":"Cuidar el margen","note":"Semana 5: Cuidar el margen. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué señales te gustaría atender antes de llegar a tu límite?","body":"Hasta tres señales propias; no se usarán como diagnóstico.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Señal 1","Señal 2","Señal 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Une una señal con una respuesta pequeña que esté a tu alcance.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a31836b8-474e-3e24-cf87-2acf9d10bb70', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 30, 'Cuidar el margen', '¿Qué podrías quitar de un día de poca energía sin descuidar una necesidad esencial?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué podrías quitar de un día de poca energía sin descuidar una necesidad esencial?","body":"Si no puedes quitar nada, nombra la ayuda que falta.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe una versión más ligera del día o el apoyo necesario para hacerla posible.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '313fb515-0f73-442e-6c54-f161ac5380c9', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 31, 'Cuidar el margen', '¿Qué suele ayudarte y qué no te ayudó, aunque pareciera un buen consejo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué suele ayudarte y qué no te ayudó, aunque pareciera un buen consejo?","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Me sirve","No me sirve por ahora"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva ambas listas; algo que no te sirve no necesita volverse una obligación.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '97736297-502e-a7dd-e658-b70ec9358a20', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 32, 'Cuidar el margen', '¿Cómo explicarías a alguien de confianza qué apoyo necesitas en un día difícil?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo explicarías a alguien de confianza qué apoyo necesitas en un día difícil?","body":"Una petición concreta, sin obligación de enviarla.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja la petición lista, manteniendo privados los detalles que no quieras compartir.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7f0a1c2f-e90c-1e5f-722f-dbc9f1c88543', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 33, 'Cuidar el margen', '¿Qué quisieras recordar cuando tengas energía para hacer más?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué quisieras recordar cuando tengas energía para hacer más?","body":"Puede ser no comprometer toda tu capacidad de los próximos días.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota un margen que quieras reservar antes de aceptar más compromisos.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'adbe32f1-d7f2-33ed-f676-b5e964cd3e83', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 34, 'Cuidar el margen', '¿Qué patrón vale la pena seguir observando y qué sigue siendo incierto?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué patrón vale la pena seguir observando y qué sigue siendo incierto?","body":"No hace falta explicar por qué ocurre ni sacar conclusiones médicas.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Separa lo observado de lo incierto; esta nota no explica por sí sola un problema de salud.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b8503332-910d-d0ed-894e-d14ffa3356fc', (SELECT id FROM path_content WHERE area = 'energy' AND locale = 'es'), 35, 'Cuidar el margen', '¿Qué nota práctica le dejarías a tu yo de un día con poca energía?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"Esta semana fue sobre «Cuidar el margen». Lo que escribiste para conservar: «{d35.ask}». Es tuyo para reutilizar, cambiar o dejar. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él.","letterFallback":"Esta semana fue sobre «Cuidar el margen». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué nota práctica le dejarías a tu yo de un día con poca energía?","body":"Completa solo las líneas que quieras.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Puedo simplificar…","Me ayuda…","Puedo pedir…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Revisa que la nota sea breve y útil incluso cuando no quieras escribir más.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('71b3fb6f-101d-d76d-daac-d760f66499d4', 'purpose', 'es', 'PROPÓSITO', 'Encontrar propósito', 'Encontrar propósito', 'solar:case-bold-duotone', '#7C6BA8', 'Vuelve a conectar con lo que de verdad te mueve.', 3, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '426fcb26-d3e6-5a81-227a-70cd6ab24d26', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 1, 'Una pregunta propia', '¿Qué tema vuelve a tu cabeza cuando por fin tienes un rato para ti?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: un foco pequeño que se puede explorar.","weekTitle":"Una pregunta propia","intro":{"title":"Una pregunta propia","note":"Semana 1: Una pregunta propia. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué tema vuelve a tu cabeza cuando por fin tienes un rato para ti?","body":"Cuenta una situación, no toda tu historia.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon un título de pocas palabras al tema que vuelve.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '18753487-98be-768a-a0e8-1cae469acf67', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 2, 'Una pregunta propia', '¿Qué ocupa tu semana y deja poco espacio para algo que te importa?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué ocupa tu semana y deja poco espacio para algo que te importa?","body":"Nombra una tensión concreta, sin asumir que puedes quitar esa obligación.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Identifica si falta tiempo, apoyo o permiso propio; no tienes que resolverlo hoy.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f95d5949-a161-927d-29ce-bfabe82f159f', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 3, 'Una pregunta propia', '¿Qué podrías mirar cinco minutos para entender algo que te da curiosidad?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué podrías mirar cinco minutos para entender algo que te da curiosidad?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Un curso","Las tareas de un trabajo","Un proyecto de alguien","Una actividad local","Otra cosa","Nada hoy"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si puedes, mira una sola fuente durante cinco minutos y anota algo que desconocías.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '07158dcb-2f0d-6352-78d8-112dc25b174d', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 4, 'Una pregunta propia', '¿Qué parte de lo que sientes que deberías querer sí elegirías tú?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte de lo que sientes que deberías querer sí elegirías tú?","body":"Si no reconoces esa presión, describe algo que te interese sin explicarlo a nadie.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Subraya una preferencia que sí reconoces como tuya.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4e6c3fe7-bca5-20e8-decf-a6e044d48a61', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 5, 'Una pregunta propia', '¿Qué tuvo un momento reciente que te gustaría repetir?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué tuvo un momento reciente que te gustaría repetir?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"maxSelections":6,"options":["Calma","Conexión","Aprender","Crear o resolver","Disfrutar","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota una condición concreta que hizo posible ese momento.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '424ee3b5-8815-3afb-2dc8-531e0ef6a3fe', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 6, 'Una pregunta propia', '¿Qué cosa quieres entender mejor, sin decidir todavía tu futuro?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué cosa quieres entender mejor, sin decidir todavía tu futuro?","body":"Hazla concreta: «Si este curso cabe en mi vida», no «Qué hacer con mi vida».","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe tu foco como una pregunta que podrías investigar.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '13cba104-48c0-33c6-6273-02453daea272', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 7, 'Una pregunta propia', '¿Qué descubrimiento de estos días quieres conservar?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Lo que tu vida necesita","letter":"Esta semana fue sobre «Una pregunta propia». Lo que escribiste para conservar: «{d7.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Lo que tu vida necesita.","letterFallback":"Esta semana fue sobre «Una pregunta propia». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Lo que tu vida necesita."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué descubrimiento de estos días quieres conservar?","body":"Puede ser una curiosidad, una preferencia o una duda más clara.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda un hallazgo y una duda, sin obligarte a resolverla.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c5847139-a4ce-2492-5c4b-6b8b6e3b8ee4', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 8, 'Lo que tu vida necesita', '¿Qué parte de tu vida funciona y no quieres perder por hacer un cambio?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: hasta tres condiciones para comparar opciones.","weekTitle":"Lo que tu vida necesita","intro":{"title":"Lo que tu vida necesita","note":"Semana 2: Lo que tu vida necesita. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte de tu vida funciona y no quieres perder por hacer un cambio?","body":"Una condición real: un vínculo, un ingreso, un horario o tiempo propio.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra una cosa que no quieres sacrificar al explorar.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1f5eb679-d94d-6867-b681-a266aa0f3aa4', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 9, 'Lo que tu vida necesita', '¿Qué condición necesita más cuidado en el cambio que imaginas?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué condición necesita más cuidado en el cambio que imaginas?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Ingresos básicos","Cuidados","Tiempo y energía","Dónde vivo","Un compromiso","Otra condición"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Convierte la condición elegida en un filtro para opciones futuras.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ea385c2a-d501-13e2-e6eb-7d730f99431c', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 10, 'Lo que tu vida necesita', '¿Qué haría más fácil explorar esto sin cambiarlo todo de golpe?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué haría más fácil explorar esto sin cambiarlo todo de golpe?","body":"Una ayuda, un dato o una versión más pequeña.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja un borrador de la ayuda o información que pedirías.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '8cc8f677-15da-6fe8-2b35-c336a5f1c506', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 11, 'Lo que tu vida necesita', '¿Qué parte de tus condiciones podría ser flexible, si alguna?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte de tus condiciones podría ser flexible, si alguna?","body":"Distingue «preferiría» de «necesito». Puede que ninguna sea flexible ahora.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca una condición como necesaria y otra como preferencia, solo si esa diferencia existe.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c985d302-bf20-14a7-6971-7e6a29ecde73', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 12, 'Lo que tu vida necesita', '¿Cuánto espacio real tienes para explorar en este momento?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Cuánto espacio real tienes para explorar en este momento?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Cinco minutos","Un rato esta semana","Tiempo regular","Solo quiero mirar","Ninguno por ahora","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Ajusta el tamaño del próximo intento al espacio real; cero también es una respuesta.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0df7b77d-941c-2f30-1c0e-10f6e99d5630', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 13, 'Lo que tu vida necesita', '¿Qué dos cosas que quieres parecen difíciles de tener a la vez?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué dos cosas que quieres parecen difíciles de tener a la vez?","body":"Dibuja dos círculos y nombra lo importante de cada uno. También puedes escribir dos frases.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Señala qué protege cada deseo antes de intentar elegir entre ellos.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c5bbaf42-b826-505a-c195-c2f277eea7db', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 14, 'Lo que tu vida necesita', '¿Qué tres cosas tendría que cuidar una opción para que encaje contigo?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Mirar posibilidades","letter":"Esta semana fue sobre «Lo que tu vida necesita». Lo que escribiste para conservar: «{d14.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Mirar posibilidades.","letterFallback":"Esta semana fue sobre «Lo que tu vida necesita». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Mirar posibilidades."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué tres cosas tendría que cuidar una opción para que encaje contigo?","body":"Hasta tres condiciones; no hace falta ordenarlas ni resolver conflictos.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Condición 1","Condición 2","Condición 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva las condiciones como lista de comparación, no como examen.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5730a578-6b1c-7dce-0150-9936b7f6afef', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 15, 'Mirar posibilidades', '¿Qué dos maneras distintas hay de explorar lo que te interesa?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: alternativas, datos faltantes y una prueba reversible.","weekTitle":"Mirar posibilidades","intro":{"title":"Mirar posibilidades","note":"Semana 3: Mirar posibilidades. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué dos maneras distintas hay de explorar lo que te interesa?","body":"Quedarte donde estás y cambiar una parte también cuenta.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Forma 1","Forma 2"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon un nombre sencillo a cada alternativa.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b1dfa9ed-bd09-17f3-ea05-55a96d6daf06', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 16, 'Mirar posibilidades', '¿Cómo sería un martes normal dentro de una de esas opciones?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo sería un martes normal dentro de una de esas opciones?","body":"Incluye una tarea cotidiana, no solo el momento ideal.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade una tarea poco glamorosa que también formaría parte de esa opción.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a690476d-f512-78ca-5b4f-906556f315bc', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 17, 'Mirar posibilidades', '¿Qué estás dando por hecho sobre esa opción que todavía no has comprobado?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué estás dando por hecho sobre esa opción que todavía no has comprobado?","body":"Nombra una suposición comprobable; no hace falta investigarla hoy.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe dónde podrías comprobar la suposición.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c78d8b9a-776b-c322-87fe-3a4545237987', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 18, 'Mirar posibilidades', '¿Qué ganarías con esa opción y qué podría pedirte a cambio?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué ganarías con esa opción y qué podría pedirte a cambio?","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Me daría…","Me pediría…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Señala un coste o beneficio que aún sea incierto.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0bb4426c-b8eb-a977-6060-6f5302113d8a', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 19, 'Mirar posibilidades', '¿Qué dato permitiría comparar mejor dos opciones que te interesan?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué dato permitiría comparar mejor dos opciones que te interesan?","body":"Si solo tienes una, compárala con mantener tu situación actual.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Prepara la misma pregunta para ambas opciones.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5e24a443-7a5f-5bfc-7f11-0f3c98a61941', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 20, 'Mirar posibilidades', '¿Cuál sería una versión pequeña y reversible de lo que quieres explorar?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cuál sería una versión pequeña y reversible de lo que quieres explorar?","body":"Por ejemplo: una muestra, una observación o un borrador antes de comprometerte.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Define dónde termina el intento antes de empezarlo.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1427e885-c300-7acc-c105-1918dd8bc052', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 21, 'Mirar posibilidades', '¿Qué quieres averiguar con ese pequeño intento?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Probar para aprender","letter":"Esta semana fue sobre «Mirar posibilidades». Lo que escribiste para conservar: «{d21.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Probar para aprender.","letterFallback":"Esta semana fue sobre «Mirar posibilidades». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Probar para aprender."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué quieres averiguar con ese pequeño intento?","body":"Una pregunta concreta; «si me gusta todo» es demasiado amplio.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige una señal observable que ayudaría a responder tu pregunta.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '042ce96f-c8ff-298f-a806-1de32731a4fe', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 22, 'Probar para aprender', '¿Qué pequeño intento quieres elegir, si alguno?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: un experimento limitado y aprendizaje sin nota.","weekTitle":"Probar para aprender","intro":{"title":"Probar para aprender","note":"Semana 4: Probar para aprender. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué pequeño intento quieres elegir, si alguno?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Probar una muestra","Observar una actividad","Hacer un borrador","Comprobar un requisito","Otro intento","Ninguno por ahora"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra una primera acción o registra que hoy no eliges ninguna.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c172db60-17c9-d6d1-5a54-b23fd3169330', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 23, 'Probar para aprender', '¿Qué límite haría que ese intento fuera manejable?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué límite haría que ese intento fuera manejable?","body":"Tiempo, esfuerzo o coste si aplica. Si no elegiste uno, puedes dejarlo vacío.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon un límite concreto; no necesitas agotar ese límite.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '953a2a1a-9c75-9291-097a-22e4f0ae0c4b', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 24, 'Probar para aprender', '¿Qué detalle te gustaría observar para saber si esa opción encaja contigo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué detalle te gustaría observar para saber si esa opción encaja contigo?","body":"Una señal concreta: interés por la tarea, horario viable o dificultad inesperada.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja escrita la señal para no juzgar la experiencia solo por el resultado.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b5d794f9-3044-1bc8-be2f-5fc50b630eac', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 25, 'Probar para aprender', '¿Qué necesitas ahora para seguir, cambiar o dejar tu intento?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué necesitas ahora para seguir, cambiar o dejar tu intento?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Menos pasos","Más información","Otro momento","Apoyo","No necesito cambiarlo","Quiero dejarlo"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Modifica una condición o decide detener el intento.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c2cef396-69cd-08ee-afe6-8074b90634df', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 26, 'Probar para aprender', '¿Qué pasó con el intento que elegiste?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué pasó con el intento que elegiste?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Lo hice","Hice una parte","Aún no lo hice","Lo cambié","Lo dejé","No elegí uno"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Registra el estado sin convertirlo en una nota de rendimiento.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0f4ea9f0-e7dd-b5f1-f608-ccd0f7e01b4a', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 27, 'Probar para aprender', '¿Qué te sorprendió, o qué barrera necesitas tener en cuenta?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué te sorprendió, o qué barrera necesitas tener en cuenta?","body":"Describe lo ocurrido sin convertirlo en una evaluación de tu capacidad.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota un hecho que cambie cómo harías otro intento.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '1b314ce4-dd77-3dd2-1e25-cc48e5d66fe7', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 28, 'Probar para aprender', '¿Qué sabes ahora y qué sigue abierto?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Una dirección por ahora","letter":"Esta semana fue sobre «Probar para aprender». Lo que escribiste para conservar: «{d28.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Una dirección por ahora.","letterFallback":"Esta semana fue sobre «Probar para aprender». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Una dirección por ahora."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué sabes ahora y qué sigue abierto?","body":"No hace falta haber terminado el intento.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Lo que sé ahora","Lo que sigue abierto"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Separa aprendizaje y pregunta pendiente en tu nota.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '28d82547-154d-0dc2-534c-90c7099aba02', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 29, 'Una dirección por ahora', '¿Sigue siendo lo mismo lo que quieres entender?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: una decisión provisional, incluyendo pausar.","weekTitle":"Una dirección por ahora","intro":{"title":"Una dirección por ahora","note":"Semana 5: Una dirección por ahora. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿Sigue siendo lo mismo lo que quieres entender?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Sí","Quiero precisarlo","Cambió bastante","Ya no me interesa","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si cambió tu foco, escribe la nueva versión en una frase.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd348bfc4-6ab2-b748-a372-17e01530ea75', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 30, 'Una dirección por ahora', '¿Qué condición tuya quedó más clara después de explorar?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué condición tuya quedó más clara después de explorar?","body":"Puede haberse confirmado, cambiado o seguido sin respuesta.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Actualiza una condición de tu lista; puedes mantenerla igual.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3d0479a1-f8cc-7f9d-ff53-90b706f2043a', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 31, 'Una dirección por ahora', '¿Qué dirección te sirve para el próximo tramo?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué dirección te sirve para el próximo tramo?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Seguir explorando","Dar un paso concreto","Mirar otra opción","Quedarme como estoy","Dejarlo por ahora","Aún no elegir"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja nombrada tu elección provisional, incluso si es pausar.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '79b4d3c8-c687-73a2-5f3c-4f3fa51267e1', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 32, 'Una dirección por ahora', '¿Qué forma tendría esa decisión durante una semana normal?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué forma tendría esa decisión durante una semana normal?","body":"Si elegiste parar, describe qué dejas de exigirte por ahora.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Describe una acción cotidiana compatible con esa decisión, o lo que dejas de hacer.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '824853e3-785b-ce7d-c41f-8e6793160bcf', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 33, 'Una dirección por ahora', '¿Qué apoyo te falta y qué parte puedes hacer sin él?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué apoyo te falta y qué parte puedes hacer sin él?","body":"«Nada sin ese apoyo» es válido; no conviertas una barrera real en obligación.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Distingue un paso posible de uno que necesita apoyo antes.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '574684ff-1806-4d37-83df-1deddaa75de3', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 34, 'Una dirección por ahora', '¿Qué señal te indicaría que conviene revisar tu decisión?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué señal te indicaría que conviene revisar tu decisión?","body":"Un cambio de horario, información nueva o una fecha que tú elijas. Sin recordatorio automático.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota la señal de revisión sin tratarla como una fecha límite.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '24d1d779-fe87-65f7-bf32-78424c2b0efa', (SELECT id FROM path_content WHERE area = 'purpose' AND locale = 'es'), 35, 'Una dirección por ahora', '¿Qué nota quieres dejarte sobre la dirección que eliges por ahora?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"Esta semana fue sobre «Una dirección por ahora». Lo que escribiste para conservar: «{d35.ask}». Es tuyo para reutilizar, cambiar o dejar. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él.","letterFallback":"Esta semana fue sobre «Una dirección por ahora». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué nota quieres dejarte sobre la dirección que eliges por ahora?","body":"Completa solo las líneas que quieras.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Me importa…","Necesito cuidar…","Elijo…","Puedo revisarlo cuando…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Relee la nota: debe reflejar tu vida actual, no justificarla ante nadie.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('89c29603-c66f-ec6b-c7d0-6c48e69cf84e', 'love', 'es', 'VÍNCULOS', 'Amor y límites', 'Amor y límites', 'solar:heart-bold-duotone', '#C2657E', 'Mira claro tus patrones en las relaciones y elige cómo llegar a ellas.', 4, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0dfbc8a8-4a5d-e1eb-aa4b-02d7e47f6d4e', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 1, 'Reconocer lo que necesitas', '¿En qué vínculo te gustaría sentirte un poco más tú esta semana?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: una necesidad traducida a una petición concreta.","weekTitle":"Reconocer lo que necesitas","intro":{"title":"Reconocer lo que necesitas","note":"Semana 1: Reconocer lo que necesitas. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿En qué vínculo te gustaría sentirte un poco más tú esta semana?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Pareja","Familia","Amistad","Personas del trabajo","Otro","Prefiero no elegir"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige un vínculo para observar esta semana, sin tener que cambiarlo.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd69d4804-bed2-6d0c-ecc9-88699cee0ace', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 2, 'Reconocer lo que necesitas', 'Piensa en un momento reciente en que te sentiste escuchada. ¿Qué hizo la otra persona que te ayudó?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Piensa en un momento reciente en que te sentiste escuchada. ¿Qué hizo la otra persona que te ayudó?","body":"Puede ser un detalle pequeño; si no recuerdas uno, escribe cómo te gustaría que te escucharan.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon nombre a la conducta que te ayudó: escuchar, preguntar o dar tiempo, por ejemplo.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3c537fda-c658-f1d9-6197-090b299fac25', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 3, 'Reconocer lo que necesitas', '¿Cuándo dijiste «está bien» y por dentro necesitabas algo distinto?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cuándo dijiste «está bien» y por dentro necesitabas algo distinto?","body":"Una situación cotidiana, sin nombres. También vale: «Esta semana no me pasó».","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Traduce ese «está bien» a una necesidad privada; si no aplica, conserva un ejemplo hipotético.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '88be5e60-62b2-6f2e-3bfa-3d9af3988466', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 4, 'Reconocer lo que necesitas', '¿Qué necesitas más de ese vínculo ahora?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué necesitas más de ese vínculo ahora?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Tiempo juntas","Espacio","Claridad","Ayuda concreta","Respeto a un límite","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Completa «Me ayudaría…» con una acción concreta.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c5e08c84-555a-a053-4a4d-f16000d1d965', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 5, 'Reconocer lo que necesitas', '¿Cómo se vería esa necesidad en una acción que otra persona pudiera entender?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo se vería esa necesidad en una acción que otra persona pudiera entender?","body":"Ejemplo: «Avísame si vas a llegar tarde», en vez de «Tenme en cuenta».","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Revisa que tu petición diga qué necesitas, sin exigir que la otra persona adivine.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd538a082-640d-dee8-8f1b-f1547cd45043', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 6, 'Reconocer lo que necesitas', 'Dibuja dos espacios: el tiempo que hoy compartes y el que quisieras reservar para ti. ¿Qué cambiarías?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Dibuja dos espacios: el tiempo que hoy compartes y el que quisieras reservar para ti. ¿Qué cambiarías?","body":"No tienen que ser iguales ni medirse. Puedes describirlos con palabras.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca un espacio que quieras reservar; no necesitas justificarlo ni negociar hoy.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '4d32e579-2ff7-326c-7f83-f0a2dc3efdcb', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 7, 'Reconocer lo que necesitas', '¿Qué necesidad te gustaría dejar de minimizar, aunque todavía no sepas pedirla?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Límites que puedes nombrar","letter":"Esta semana fue sobre «Reconocer lo que necesitas». Lo que escribiste para conservar: «{d7.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Límites que puedes nombrar.","letterFallback":"Esta semana fue sobre «Reconocer lo que necesitas». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Límites que puedes nombrar."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué necesidad te gustaría dejar de minimizar, aunque todavía no sepas pedirla?","body":"Completa: «Para mí también importa…». No hace falta compartirlo.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda la frase como referencia para una futura conversación.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'fd86c224-ca9a-f238-8962-57622ff9c546', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 8, 'Límites que puedes nombrar', '¿Qué petición reciente te hizo pensar «no quiero, pero debería»?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: un borrador de límite y una opción segura.","weekTitle":"Límites que puedes nombrar","intro":{"title":"Límites que puedes nombrar","note":"Semana 2: Límites que puedes nombrar. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué petición reciente te hizo pensar «no quiero, pero debería»?","body":"Si no hubo ninguna, elige una petición hipotética y pequeña.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe qué quieres responder antes de pensar cómo agradar.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '646f9e58-8ffb-ea03-42d4-685e5129fcdb', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 9, 'Límites que puedes nombrar', '¿Qué hace difícil decir que no en esa situación?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué hace difícil decir que no en esa situación?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Temo decepcionar","Necesito su ayuda","No sé qué decir","Temo una reacción","Sí quiero, pero no puedo","Otra razón"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si temes una reacción, deja el ejercicio privado y prioriza apoyo; no ensayes confrontaciones.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f40242d8-a62e-d7f8-1718-7420681475d7', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 10, 'Límites que puedes nombrar', '¿Qué sí puedes ofrecer sin prometer algo que no quieres sostener?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué sí puedes ofrecer sin prometer algo que no quieres sostener?","body":"También es válido no ofrecer una alternativa.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Distingue una alternativa que deseas ofrecer de una que ofreces por obligación.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9d448093-587b-a831-2064-a466e30691ff', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 11, 'Límites que puedes nombrar', '¿Cómo sonaría un límite breve, sin explicar toda tu historia?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo sonaría un límite breve, sin explicar toda tu historia?","body":"Borrador privado: «Hoy no puedo…» o «Puedo…, pero no…». No hace falta enviarlo.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Reduce el borrador a una o dos frases claras.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f26486b5-9c66-6c4a-4789-5b542145c588', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 12, 'Límites que puedes nombrar', 'Si insisten, ¿qué frase podrías repetir sin entrar en una discusión?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"Si insisten, ¿qué frase podrías repetir sin entrar en una discusión?","body":"Solo ensáyala si resulta seguro. Puedes elegir no responder.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda una frase de repetición o una opción de no responder.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7a286385-2711-4401-3f39-4878b0315c7b', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 13, 'Límites que puedes nombrar', '¿Qué opción te cuida más en esta situación concreta?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué opción te cuida más en esta situación concreta?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Pedir tiempo","Decir no","Negociar una parte","Pedir apoyo","No responder por ahora","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra el siguiente paso más seguro, aunque sea esperar.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6f0ad872-5009-285b-03c5-4753ebaa4c26', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 14, 'Límites que puedes nombrar', '¿Qué aprendiste al escribir el límite, aunque no lo hayas dicho?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Hacer espacio a la conexión","letter":"Esta semana fue sobre «Límites que puedes nombrar». Lo que escribiste para conservar: «{d14.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Hacer espacio a la conexión.","letterFallback":"Esta semana fue sobre «Límites que puedes nombrar». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Hacer espacio a la conexión."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué aprendiste al escribir el límite, aunque no lo hayas dicho?","body":"Puede ser claridad, incomodidad o que necesitas apoyo antes de actuar.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota qué apoyo necesitarías antes de decirlo, si quieres hacerlo.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'bc07ceff-42ae-f3db-e0bf-afdb1fc6b245', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 15, 'Hacer espacio a la conexión', '¿Qué tipo de compañía extrañas, más allá de «tener gente»?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: una invitación posible sin presión ni exposición.","weekTitle":"Hacer espacio a la conexión","intro":{"title":"Hacer espacio a la conexión","note":"Semana 3: Hacer espacio a la conexión. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué tipo de compañía extrañas, más allá de «tener gente»?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Conversar sin prisa","Hacer algo juntas","Reír","Sentirme comprendida","Ayuda cotidiana","No extraño compañía ahora"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Convierte el tipo de compañía elegido en una actividad pequeña posible.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '04d81a56-b50c-a2d6-d3da-3969ed77c2d6', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 16, 'Hacer espacio a la conexión', '¿Con quién podrías tener un contacto pequeño sin tener que contarle todo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Con quién podrías tener un contacto pequeño sin tener que contarle todo?","body":"Usa una inicial o describe un espacio; no hace falta un nombre.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige un contacto o espacio que respete tu privacidad; contactar sigue siendo opcional.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a1137b03-ee5c-0ce7-88f9-65c9ec3b8156', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 17, 'Hacer espacio a la conexión', '¿Qué invitación sería fácil de aceptar o rechazar sin presión?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué invitación sería fácil de aceptar o rechazar sin presión?","body":"Escribe un borrador con actividad y margen: «¿Te gustaría…? Si no puedes, todo bien».","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja la invitación lista, sin insistencia ni obligación de enviarla.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '791a06f6-7516-fc80-989f-9fb2e68de50d', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 18, 'Hacer espacio a la conexión', '¿Qué te ayudaría a estar presente en una conversación breve?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué te ayudaría a estar presente en una conversación breve?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Apartar el teléfono","Elegir un momento tranquilo","Decir que tengo poco tiempo","Escuchar sin resolver","Pedir que me escuchen","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige una sola condición para tu próxima conversación.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '60c841a2-78ff-f526-8488-b5efaa4cdf35', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 19, 'Hacer espacio a la conexión', '¿Qué pregunta le harías para conocer su experiencia sin dar consejos enseguida?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué pregunta le harías para conocer su experiencia sin dar consejos enseguida?","body":"Escribe una pregunta que no suponga cómo se siente.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva la pregunta y deja espacio para escuchar la respuesta.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ce4948c7-fba2-f821-1d42-edf6410b956e', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 20, 'Hacer espacio a la conexión', '¿Cómo resultó tu intento de conectar, si hiciste uno?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Cómo resultó tu intento de conectar, si hiciste uno?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Conectamos","Quedó pendiente","No pudo","No me hizo bien","No lo intenté","Elegí estar sola"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Registra lo ocurrido sin interpretar el silencio como rechazo seguro.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0b22d4fe-7bac-1bfc-145b-1126068a7d8e', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 21, 'Hacer espacio a la conexión', '¿Qué gesto de conexión te gustaría repetir, adaptar o dejar atrás?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Desacuerdos con cuidado","letter":"Esta semana fue sobre «Hacer espacio a la conexión». Lo que escribiste para conservar: «{d21.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Desacuerdos con cuidado.","letterFallback":"Esta semana fue sobre «Hacer espacio a la conexión». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Desacuerdos con cuidado."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué gesto de conexión te gustaría repetir, adaptar o dejar atrás?","body":"Una respuesta ajena no mide tu valor. Elige por cómo encaja en tu vida.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige repetir, adaptar o soltar ese gesto según tu experiencia.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7e77b8ca-e97b-1d9d-e765-5b446a7ea761', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 22, 'Desacuerdos con cuidado', 'En un desacuerdo pequeño, ¿qué ocurrió y qué interpretación añadiste tú?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: distinguir hechos, responsabilidad y condiciones para hablar.","weekTitle":"Desacuerdos con cuidado","intro":{"title":"Desacuerdos con cuidado","note":"Semana 4: Desacuerdos con cuidado. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"blanks","title":"En un desacuerdo pequeño, ¿qué ocurrió y qué interpretación añadiste tú?","body":"Puedes usar un ejemplo inventado.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Lo que observé","Lo que supuse"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Señala una interpretación que necesitaría aclaración antes de tratarla como hecho.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7ad87285-3db1-d9fd-eb35-4de8243a7933', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 23, 'Desacuerdos con cuidado', '¿Qué quisieras que la otra persona entendiera, sin tener que ganar la discusión?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué quisieras que la otra persona entendiera, sin tener que ganar la discusión?","body":"Elige una sola cosa. No hace falta iniciar esa conversación.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Redacta una frase que empiece por lo que observaste y lo que necesitas.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'eb15b307-ffd3-992a-6da1-ef7223689052', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 24, 'Desacuerdos con cuidado', '¿Qué parte, si alguna, te corresponde reparar?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte, si alguna, te corresponde reparar?","body":"Distingue tu acción de la reacción ajena. «Ninguna» puede ser una respuesta válida.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si corresponde, prepara una reparación específica sin asumir toda la culpa.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '367e4983-19cd-3117-5b88-b9b91dc46cd9', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 25, 'Desacuerdos con cuidado', '¿Cómo pedirías una pausa sin prometer volver antes de estar lista?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo pedirías una pausa sin prometer volver antes de estar lista?","body":"Ensaya una frase privada. Si hablar no es seguro, elige buscar apoyo.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una frase de pausa que no exija resolver el desacuerdo de inmediato.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd42c59eb-a482-9068-febb-81d1ae8046c2', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 26, 'Desacuerdos con cuidado', '¿Qué señal te indicaría que esta conversación puede continuar con respeto?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué señal te indicaría que esta conversación puede continuar con respeto?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"exclusiveOption":4,"optional":true,"maxSelections":5,"options":["Podemos terminar una frase","No hay insultos","Se respeta la pausa","Puedo discrepar","No veo esas condiciones"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Identifica una condición mínima para continuar; no conversar también puede ser una opción.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0e97017f-94dd-ab4c-39e3-22c5e9e90ef2', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 27, 'Desacuerdos con cuidado', '¿Qué te conviene hacer con este desacuerdo por ahora?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué te conviene hacer con este desacuerdo por ahora?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Aclarar algo","Reparar mi parte","Dejarlo reposar","Buscar apoyo","Mantener distancia","No decidir aún"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra un paso que dependa de ti, sin exigir una respuesta de la otra persona.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7972d50f-4d8b-6a7c-d465-c8bff3ecdac5', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 28, 'Desacuerdos con cuidado', '¿Qué diferencia notas entre cuidar un vínculo y hacerte cargo de todo?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Vínculos sostenibles","letter":"Esta semana fue sobre «Desacuerdos con cuidado». Lo que escribiste para conservar: «{d28.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Vínculos sostenibles.","letterFallback":"Esta semana fue sobre «Desacuerdos con cuidado». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Vínculos sostenibles."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué diferencia notas entre cuidar un vínculo y hacerte cargo de todo?","body":"Usa un ejemplo concreto, real o imaginado.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe una responsabilidad compartida que no quieras asumir sola.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '462c39c8-7bbf-4a37-0da5-eacb4103d026', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 29, 'Vínculos sostenibles', '¿Qué gesto pequeño te ha hecho sentir querida de una forma que sí te llega?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una nota de necesidades, apoyo y ritmo de contacto.","weekTitle":"Vínculos sostenibles","intro":{"title":"Vínculos sostenibles","note":"Semana 5: Vínculos sostenibles. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué gesto pequeño te ha hecho sentir querida de una forma que sí te llega?","body":"Si no recuerdas uno, describe uno que te gustaría recibir.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda el gesto como ejemplo para explicar lo que sí te llega.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'efbacdbd-ccbb-8029-a3e5-eef4fd47cd87', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 30, 'Vínculos sostenibles', '¿Qué podrías pedir con más claridad la próxima vez?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué podrías pedir con más claridad la próxima vez?","body":"Completa: «Me ayudaría que…». No es una obligación enviarlo.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Haz la petición concreta y deja que la otra persona pueda responder honestamente.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7bc5daf0-11a7-e987-4df3-a89c86ea1968', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 31, 'Vínculos sostenibles', '¿Qué apoyo quieres mantener fuera de un solo vínculo?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué apoyo quieres mantener fuera de un solo vínculo?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Gracias. Con eso basta para trabajar.","config":{"exclusiveOption":5,"optional":true,"maxSelections":6,"options":["Amistades","Familia elegida","Comunidad","Apoyo profesional","Tiempo propio","Aún no sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Nombra una fuente de apoyo adicional o una que te gustaría encontrar.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'fc3b60b3-9c37-cc71-69c2-f485f2294343', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 32, 'Vínculos sostenibles', '¿Qué límite sigue siendo importante incluso cuando estás de buen ánimo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué límite sigue siendo importante incluso cuando estás de buen ánimo?","body":"Escribe una frase que quieras poder releer.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva el límite sin endurecerlo como castigo ni retirarlo por culpa.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '9e5231db-3898-16a9-7c6d-a0bd34cf7b6b', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 33, 'Vínculos sostenibles', '¿Qué ritmo de contacto te resulta sostenible esta temporada?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué ritmo de contacto te resulta sostenible esta temporada?","body":"Puede ser espontáneo, ocasional o con un acuerdo. Evita prometer una frecuencia por culpa.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Describe un ritmo posible y una forma de revisarlo si cambian las circunstancias.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'a86b6661-37b1-8ae4-971d-cea3330a1525', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 34, 'Vínculos sostenibles', '¿Qué reconoces ahora sobre cómo quieres querer y ser querida?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué reconoces ahora sobre cómo quieres querer y ser querida?","body":"Incluye una necesidad y una acción posible; ninguna tiene que sonar bonita.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Extrae una frase que usarías en una conversación real, solo si te sirve.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '77cb5341-d1d0-0821-f464-3aceea033cd6', (SELECT id FROM path_content WHERE area = 'love' AND locale = 'es'), 35, 'Vínculos sostenibles', '¿Qué quieres llevarte de este camino para tu próximo vínculo o conversación?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"Esta semana fue sobre «Vínculos sostenibles». Lo que escribiste para conservar: «{d35.ask}». Es tuyo para reutilizar, cambiar o dejar. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él.","letterFallback":"Esta semana fue sobre «Vínculos sostenibles». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué quieres llevarte de este camino para tu próximo vínculo o conversación?","body":"Completa solo las líneas que quieras.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Necesito…","Puedo pedir…","No tengo que…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Revisa que tu nota incluya tus necesidades y tu margen para elegir.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_content (id, area, locale, label, name, area_name, icon, accent, tagline, sort_order, published) VALUES ('276803ee-c6df-5c9e-efee-501d6846c5f2', 'everyday', 'es', 'LO COTIDIANO', 'Ritmo diario', 'Ritmo diario', 'solar:armchair-bold-duotone', '#5E8B7E', 'Baja la fricción diaria que te va consumiendo sin que lo notes.', 5, 1) ON CONFLICT(area, locale) DO UPDATE SET label=excluded.label, name=excluded.name, area_name=excluded.area_name, icon=excluded.icon, accent=excluded.accent, tagline=excluded.tagline, sort_order=excluded.sort_order, updated_at=(unixepoch());
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0c28d513-c957-2ac1-6dc2-3454b1b9a24f', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 1, 'Ver la carga real', '¿En qué momento del día sientes que todo se te junta?', NULL, 'reflect', '{"minutes":3,"payoff":"Para llevarte esta semana: un momento difícil descrito sin culparse.","weekTitle":"Ver la carga real","intro":{"title":"Ver la carga real","note":"Semana 1: Ver la carga real. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"choose","title":"¿En qué momento del día sientes que todo se te junta?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Al despertar","Al salir","A media jornada","Al volver","Antes de dormir","Mi horario cambia"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige un momento, no todo el día, para observar esta semana.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'dd2920f4-7cfe-f5e9-bae6-7e70c071ec51', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 2, 'Ver la carga real', 'Reconstruye ese momento de ayer: ¿qué estabas intentando hacer a la vez?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"Reconstruye ese momento de ayer: ¿qué estabas intentando hacer a la vez?","body":"Hasta tres tareas, sin juzgar cómo salieron.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Tarea 1","Tarea 2","Tarea 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Pon las tareas en el orden en que aparecieron.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e9a02ada-258a-25b6-56ef-9add31192c55', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 3, 'Ver la carga real', '¿Qué trabajo haces ahí que nadie suele contar como trabajo?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué trabajo haces ahí que nadie suele contar como trabajo?","body":"Puede ser recordar, coordinar, cuidar o anticipar. Si no aplica, escribe otra carga.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade esa carga invisible a tu descripción del momento.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'b38b6c02-ab06-1b7c-3240-12a3fb6ef06c', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 4, 'Ver la carga real', '¿Qué parte depende de ti y qué parte depende de horarios o necesidades ajenas?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte depende de ti y qué parte depende de horarios o necesidades ajenas?","body":"Dos zonas, con palabras o trazos. Puedes usar dos listas.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["draw","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Marca una parte que puedas ajustar y otra que requiera apoyo o coordinación.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '3c7465ae-4da5-4993-e07d-85e0a714900d', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 5, 'Ver la carga real', '¿Qué cambio pequeño quitaría un paso de ese momento?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué cambio pequeño quitaría un paso de ese momento?","body":"No añadas una rutina completa: elige algo que simplifique.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe exactamente qué paso dejaría de ser necesario.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '26b09457-179d-46a9-f5b1-a9f261dac430', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 6, 'Ver la carga real', '¿Qué tienes disponible para probar ese cambio?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué tienes disponible para probar ese cambio?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["Unos minutos","Un objeto a mano","Ayuda de alguien","Puedo cambiar el orden","Nada por ahora","No lo sé"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Adapta el cambio a un recurso disponible, o deja registrada la barrera.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e5f8b87f-af72-abfc-c458-9a12eeb576fc', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 7, 'Ver la carga real', '¿Qué parte del día merece menos exigencia, no más disciplina?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Quitar fricción","letter":"Esta semana fue sobre «Ver la carga real». Lo que escribiste para conservar: «{d7.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Quitar fricción.","letterFallback":"Esta semana fue sobre «Ver la carga real». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Quitar fricción."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte del día merece menos exigencia, no más disciplina?","body":"Nombra el momento y una expectativa que podrías bajar.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una expectativa más realista para ese momento del día.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '768cead0-6df7-c4f1-4d64-2c6eb7a51fb2', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 8, 'Quitar fricción', '¿Qué tarea pequeña se vuelve difícil porque hay demasiados pasos antes?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una tarea con menos pasos y una versión mínima.","weekTitle":"Quitar fricción","intro":{"title":"Quitar fricción","note":"Semana 2: Quitar fricción. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué tarea pequeña se vuelve difícil porque hay demasiados pasos antes?","body":"Elige algo cotidiano y concreto.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Enumera solo los pasos previos al inicio de la tarea.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '63bb1e19-5c20-cde8-e659-ccf01db411fd', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 9, 'Quitar fricción', '¿Cuál es el primer obstáculo que encuentras al empezar?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Cuál es el primer obstáculo que encuentras al empezar?","body":"Elige una.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"options":["No encuentro algo","No sé por dónde","Me interrumpen","Requiere preparar mucho","No tengo tiempo","Otro"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige un obstáculo para reducir, sin rediseñar toda tu vida.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'eb1db8bc-7d8d-6698-a3d6-e050aafc2644', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 10, 'Quitar fricción', '¿Qué podrías dejar listo sin crear otra tarea pesada?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"photo","title":"¿Qué podrías dejar listo sin crear otra tarea pesada?","body":"Foto opcional de un objeto o rincón sin datos personales; también puedes describirlo.","elara":"Gracias. Con eso basta para trabajar.","config":{"quiet":true,"optional":true,"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Si puedes, prepara una sola cosa; la foto no es necesaria para completar el día.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '393392d0-0bfc-69d1-3074-c1c1c54fcb18', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 11, 'Quitar fricción', '¿A qué momento que ya ocurre podrías unir ese primer paso?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿A qué momento que ya ocurre podrías unir ese primer paso?","body":"Si tus horarios cambian, usa un evento: «Después de llegar…».","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Redacta una señal de inicio basada en un evento real.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f914dde8-6166-9e4c-937d-c944042224b5', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 12, 'Quitar fricción', '¿Cuál sería una versión suficientemente útil para un día complicado?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cuál sería una versión suficientemente útil para un día complicado?","body":"No tiene que cumplir la versión ideal. Define lo mínimo que te serviría.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja escrita la versión pequeña junto a la habitual.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0fe52eaf-75b6-3c4b-f229-50219498d219', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 13, 'Quitar fricción', '¿Qué ocurrió cuando lo probaste o pensaste probarlo?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué ocurrió cuando lo probaste o pensaste probarlo?","body":"Elige una.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"options":["Fue más fácil","Igual de difícil","Añadió trabajo","Me interrumpieron","No lo probé","Ya no me sirve"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota qué ocurrió justo antes de que el plan ayudara o fallara.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c2527aff-0f53-77f1-4f01-9461dd659181', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 14, 'Quitar fricción', '¿Qué paso puedes quitar o mover después de lo que observaste?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Compartir y coordinar","letter":"Esta semana fue sobre «Quitar fricción». Lo que escribiste para conservar: «{d14.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Compartir y coordinar.","letterFallback":"Esta semana fue sobre «Quitar fricción». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Compartir y coordinar."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué paso puedes quitar o mover después de lo que observaste?","body":"Si no lo probaste, identifica la preparación que faltaba o decide soltarlo.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Modifica un paso o descarta el experimento si añade más carga.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f521ae73-81f6-a4e3-5cfb-e17f7e299bc8', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 15, 'Compartir y coordinar', '¿Qué petición o interrupción suele desordenar tus planes?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una petición concreta o un ajuste de alcance.","weekTitle":"Compartir y coordinar","intro":{"title":"Compartir y coordinar","note":"Semana 3: Compartir y coordinar. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué petición o interrupción suele desordenar tus planes?","body":"Elige una que se repita; no hace falta identificar a nadie.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Anota si esa interrupción es previsible o necesita margen extra.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c112d3b1-3280-11b6-45b4-152bc2b33fe8', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 16, 'Compartir y coordinar', '¿Qué interrupciones requieren atención inmediata de verdad?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué interrupciones requieren atención inmediata de verdad?","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Necesita atención ahora","Puede esperar en mi contexto"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva una distinción útil entre urgente y pendiente en tu contexto.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e2e22e2e-8d46-e403-1893-29b8c37b4a72', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 17, 'Compartir y coordinar', '¿Qué ayuda podrías pedir como tarea completa, en vez de tener que dirigir cada paso?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué ayuda podrías pedir como tarea completa, en vez de tener que dirigir cada paso?","body":"Si no hay quien ayude, escribe una tarea que puedas reducir o posponer.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Redacta la petición con el resultado necesario, no una lista de órdenes.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e29d0fc8-ddac-4a7f-47c2-ac78919cb1db', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 18, 'Compartir y coordinar', '¿Cómo expresarías cuándo sí puedes atender una petición?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo expresarías cuándo sí puedes atender una petición?","body":"Ensaya una frase concreta sin prometer disponibilidad que no tienes.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja una frase con un momento realista para responder.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ea0f0185-2bf8-64f3-f7fd-f94ddfa06d22', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 19, 'Compartir y coordinar', '¿Qué compromiso de esta semana ocupa más de lo que pensabas?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué compromiso de esta semana ocupa más de lo que pensabas?","body":"Incluye preparación, traslados o recuperación si aplica.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Añade al compromiso el tiempo de preparación que antes no contabas.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'c49e6498-926a-ca30-f609-93fb1e296858', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 20, 'Compartir y coordinar', '¿Qué ajuste es posible sin dejar desatendida una necesidad importante?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué ajuste es posible sin dejar desatendida una necesidad importante?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Cambiar horario","Reducir alcance","Repartir tarea","Pedir más plazo","Ninguno por ahora","Necesito pensarlo"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe el ajuste y qué necesidad importante debe seguir cubierta.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'f77260f2-3309-5d09-98d3-91c5324724b6', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 21, 'Compartir y coordinar', '¿Qué conversación o ajuste aliviaría más coordinación la próxima semana?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Días que se tuercen","letter":"Esta semana fue sobre «Compartir y coordinar». Lo que escribiste para conservar: «{d21.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Días que se tuercen.","letterFallback":"Esta semana fue sobre «Compartir y coordinar». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Días que se tuercen."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué conversación o ajuste aliviaría más coordinación la próxima semana?","body":"Deja un borrador; no hace falta enviarlo.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Guarda un acuerdo propuesto con quién hace qué, si hay otra persona disponible.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0d04d779-f6d5-f116-cc82-b35c6497012a', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 22, 'Días que se tuercen', 'Piensa en un día que se torció. ¿Qué necesitaba seguir funcionando y qué podía esperar?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: un plan mínimo y un punto de reentrada.","weekTitle":"Días que se tuercen","intro":{"title":"Días que se tuercen","note":"Semana 4: Días que se tuercen. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"blanks","title":"Piensa en un día que se torció. ¿Qué necesitaba seguir funcionando y qué podía esperar?","body":"Hasta dos cosas por grupo.","elara":"Gracias. Con eso basta para trabajar.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Debe seguir funcionando (1)","Debe seguir funcionando (2)","Puede esperar (1)","Puede esperar (2)"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva la lista de lo esencial separada de lo que puede esperar.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '5d84a9f2-5634-fc27-5533-badc9b5fd010', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 23, 'Días que se tuercen', '¿Qué señal temprana te dice que necesitas simplificar el día?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"choose","title":"¿Qué señal temprana te dice que necesitas simplificar el día?","body":"Elige una.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"options":["Voy con retraso","Olvido pasos","Cambió el cuidado de alguien","Apareció un imprevisto","Tengo menos energía","Otra señal"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Vincula la señal elegida con una simplificación concreta.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e209628f-b210-af92-4df8-3ace9d5c68d3', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 24, 'Días que se tuercen', '¿Cómo sería tu versión de día mínimo sin abandonarte a ti misma?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Cómo sería tu versión de día mínimo sin abandonarte a ti misma?","body":"Hasta tres necesidades reales, no una lista de productividad.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"optional":true,"skipLabel":"Prefiero pasar","fields":["Necesidad 1","Necesidad 2","Necesidad 3"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Revisa que los mínimos sean necesidades y no una lista ideal disfrazada.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'ff714009-2347-79d3-5bdb-ff48edc20b39', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 25, 'Días que se tuercen', '¿Qué podrías dejar por escrito para no decidirlo todo otra vez en un día difícil?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué podrías dejar por escrito para no decidirlo todo otra vez en un día difícil?","body":"Una secuencia breve o una frase de permiso concreta.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja la nota en un lugar privado donde puedas volver a verla.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '7cf54b51-b9fc-c8d8-1d51-7e3a85e47ad6', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 26, 'Días que se tuercen', '¿Qué te ayudaría a retomar una tarea sin recuperar todos los días perdidos?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué te ayudaría a retomar una tarea sin recuperar todos los días perdidos?","body":"Elige un punto de entrada pequeño, sin deuda de tareas.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe un punto de reentrada que no exija compensar el pasado.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '2f0cd2fd-b529-7985-8b32-1737a6187348', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 27, 'Días que se tuercen', '¿Qué parte de tu plan necesita adaptarse a tu vida real?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué parte de tu plan necesita adaptarse a tu vida real?","body":"Nombra una condición: turnos, cuidados, espacio, transporte u otra.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Ajusta el plan a esa condición en vez de tratarla como una excusa.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'd04bc86a-87e5-39d9-ad96-3fa2ebd07840', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 28, 'Días que se tuercen', '¿Qué dejarías preparado para tu próximo día complicado?', NULL, 'reflect', '{"minutes":4,"header":"centered","nextWeekTitle":"Un ritmo que se adapta","letter":"Esta semana fue sobre «Días que se tuercen». Lo que escribiste para conservar: «{d28.ask}». Es tuyo para reutilizar, cambiar o dejar. La semana que viene: Un ritmo que se adapta.","letterFallback":"Esta semana fue sobre «Días que se tuercen». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. La semana que viene: Un ritmo que se adapta."}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué dejarías preparado para tu próximo día complicado?","body":"Puede ser una lista de mínimos o una decisión ya tomada.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"keep":"rule","modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva una decisión adelantada que quite carga, no otra obligación.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '088dd401-46d5-7e4e-fac3-beaea0a86f09', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 29, 'Un ritmo que se adapta', '¿Qué cambio de estas semanas te quitó trabajo de verdad?', NULL, 'reflect', '{"minutes":4,"payoff":"Para llevarte esta semana: una guía breve para semanas imperfectas.","weekTitle":"Un ritmo que se adapta","intro":{"title":"Un ritmo que se adapta","note":"Semana 5: Un ritmo que se adapta. Cada pregunta es opcional: puedes omitir una, usar un ejemplo en lugar de tu situación y mantener en privado lo que quieras. Nada de aquí te pide contactar a nadie, gastar dinero ni compartir lo que escribes."}}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué cambio de estas semanas te quitó trabajo de verdad?","body":"«Ninguno todavía» también sirve: anota qué lo impidió.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Señala qué cambio conservarías por su utilidad real.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6719dbec-d45c-74f8-3a8d-1a897218060c', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 30, 'Un ritmo que se adapta', '¿Qué rutina estás manteniendo por costumbre aunque ya no te ayude?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué rutina estás manteniendo por costumbre aunque ya no te ayude?","body":"Si todas sirven, elige una que quieras proteger.","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Elige mantener, reducir o retirar esa rutina.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '60795b4e-a2aa-f9d3-0f6b-6741ac01e22c', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 31, 'Un ritmo que se adapta', '¿Qué momento quieres dejar sin optimizar?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué momento quieres dejar sin optimizar?","body":"No hace falta convertir todo descanso o disfrute en una meta.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Deja ese momento sin seguimiento ni una meta de rendimiento.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '0b1d453b-71f7-0e36-ac0b-04223cfafcb0', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 32, 'Un ritmo que se adapta', '¿Qué necesitas revisar cuando cambian tus horarios?', NULL, 'reflect', '{"minutes":3}', NULL, '[{"id":"ask","kind":"multi","title":"¿Qué necesitas revisar cuando cambian tus horarios?","body":"Elige las que encajen. También puedes no elegir ninguna.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"maxSelections":6,"options":["Orden de tareas","Tiempo de traslado","Reparto de cuidados","Espacio para mí","Compromisos","Otra cosa"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Haz una lista breve para revisar cuando el horario cambie.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '6e5d765c-3e00-6a22-579e-b89427a3fced', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 33, 'Un ritmo que se adapta', '¿Cómo te gustaría revisar tu semana sin evaluarte como persona?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Cómo te gustaría revisar tu semana sin evaluarte como persona?","body":"Elige dos preguntas prácticas, por ejemplo: «¿Qué sobró? ¿Qué faltó?».","elara":"Anotado. Nada de esto tiene que ser perfecto.","config":{"minWords":1,"optional":true,"modes":["write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Conserva tus dos preguntas como revisión opcional, sin puntuación.","elara":"Sea lo que sea que escribiste, puedes volver a ello.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT 'e272c5cd-c8dd-e375-cdac-7b651bfbeb42', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 34, 'Un ritmo que se adapta', '¿Qué acuerdo contigo misma sería sostenible durante una semana imperfecta?', NULL, 'reflect', '{"minutes":4}', NULL, '[{"id":"ask","kind":"reflect","title":"¿Qué acuerdo contigo misma sería sostenible durante una semana imperfecta?","body":"Incluye una versión pequeña y permiso para revisarla.","elara":"Gracias. Con eso basta para trabajar.","config":{"minWords":1,"optional":true,"modes":["say","write"],"skipLabel":"Prefiero pasar"}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Escribe la versión para una semana difícil junto a la habitual.","elara":"Es tuyo para conservar, cambiar o dejar.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
INSERT INTO path_day (id, path_content_id, day, level, title, body, kind, config, elara, steps) SELECT '57134242-fa27-2cbb-1aa2-c9a154a4445d', (SELECT id FROM path_content WHERE area = 'everyday' AND locale = 'es'), 35, 'Un ritmo que se adapta', '¿Qué instrucciones útiles le dejarías a tu yo de una semana muy ocupada?', NULL, 'reflect', '{"minutes":4,"header":"centered","letter":"Esta semana fue sobre «Un ritmo que se adapta». Lo que escribiste para conservar: «{d35.ask}». Es tuyo para reutilizar, cambiar o dejar. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él.","letterFallback":"Esta semana fue sobre «Un ritmo que se adapta». Lo que respondiste, omitiste o dejaste para después sigue siendo tuyo: nada de aquí es una calificación. Ese es todo el camino. Cualquier día sigue ahí si quieres volver a él."}', NULL, '[{"id":"ask","kind":"blanks","title":"¿Qué instrucciones útiles le dejarías a tu yo de una semana muy ocupada?","body":"Completa solo las líneas que quieras.","elara":"Eso ayuda. Puedes cambiarlo cuando quieras.","config":{"optional":true,"keep":"rule","skipLabel":"Prefiero pasar","fields":["Prioriza…","Simplifica…","Puede esperar…"]}},{"id":"take","kind":"reflect","title":"Para llevarte","body":"Revisa que las tres líneas reduzcan decisiones en vez de añadir tareas.","elara":"Algo pequeño y claro es suficiente. Se queda contigo.","config":{"minWords":1,"optional":true,"keep":"sentence","modes":["write"],"skipLabel":"Prefiero pasar"}}]' WHERE true ON CONFLICT(path_content_id, day) DO UPDATE SET level=excluded.level, title=excluded.title, body=excluded.body, kind=excluded.kind, config=excluded.config, elara=excluded.elara, steps=COALESCE(excluded.steps, path_day.steps);
